	var hosts []Instance
	for index, key := range []string{"selected-a", "other-b", "other-c"} {
		request := testEnsureRequest(entityid.Derive("test-operation", key))
		request.PrivateIP = []string{"10.251.0.31", "10.251.0.32", "10.251.0.33"}[index]
