func testMemberVolumeConfig() MemberVolumeConfig {
	return MemberVolumeConfig{Region: "GRU", CompartmentID: "ocid1.compartment.members", AvailabilityDomain: "AD-1", VPUsPerGB: 10}
}

// memberVolumeFixture builds MemberVolumes over the shared fake provider, or
// over provider when one is given. Created volumes become AVAILABLE at once.
func memberVolumeFixture(t *testing.T, provider Provider) (*MemberVolumes, *fakeProvider) {
	t.Helper()
	config := testMemberVolumeConfig()
	regionConfig, err := config.regionConfig()
	if err != nil {
		t.Fatal(err)
	}
	var fake *fakeProvider
	switch typed := provider.(type) {
	case nil:
		fake = newFakeProvider(regionConfig)
		provider = fake
	case *resizeProvider:
		fake = typed.fakeProvider
	default:
		t.Fatalf("unsupported provider %T", provider)
	}
	fake.afterVolumeCreate = func() { setVolumeStates(fake, "PROVISIONING", "AVAILABLE") }
	volumes, err := newMemberVolumes(config, provider)
	if err != nil {
		t.Fatal(err)
	}
	volumes.fleet.attachmentSettle = 50 * time.Millisecond
	return volumes, fake
}

func setVolumeStates(p *fakeProvider, from, to string) {
	for id, volume := range p.volumes {
		if volume.LifecycleState == from {
			volume.LifecycleState = to
			p.volumes[id] = volume
		}
	}
}

func addMemberInstance(p *fakeProvider, id, displayName string) CloudInstance {
	instance := CloudInstance{
		ID: id, DisplayName: displayName, CompartmentID: p.config.CompartmentID, AvailabilityDomain: p.config.AvailabilityDomain,
		LifecycleState: "RUNNING", ETag: "instance-etag", ConsistentVolumeNamingEnabled: boolPointer(true),
	}
	p.instances[id] = instance
	return instance
}

func onlyVolume(t *testing.T, p *fakeProvider) CloudVolume {
	t.Helper()
	if len(p.volumes) != 1 {
		t.Fatalf("volumes = %d, want 1", len(p.volumes))
	}
	for _, volume := range p.volumes {
		return volume
	}
	return CloudVolume{}
}

func setAttachmentState(p *fakeProvider, id, state string) {
	attachment := p.attachments[id]
	attachment.LifecycleState = state
	p.attachments[id] = attachment
}

func (p *fakeProvider) ListVolumeBackupPolicies(context.Context) ([]CloudBackupPolicy, error) {
	return slices.Clone(p.backupPolicies), nil
}

func (p *fakeProvider) CreateVolumeBackupPolicy(_ context.Context, name string, schedules []BackupSchedule, tags map[string]string, retry string) (CloudBackupPolicy, error) {
	if p.backupPolicyRetryTokens == nil {
		p.backupPolicyRetryTokens = make(map[string]string)
	}
	for _, policy := range p.backupPolicies {
		if p.backupPolicyRetryTokens[retry] == policy.ID {
			return policy, nil
		}
	}
	p.backupPolicyCreates++
	policy := CloudBackupPolicy{ID: fmt.Sprintf("ocid1.volumebackuppolicy.created-%d", p.backupPolicyCreates), DisplayName: name,
		Schedules: slices.Clone(schedules), FreeformTags: cloneStringMap(tags)}
	p.backupPolicies = append(p.backupPolicies, policy)
	p.backupPolicyRetryTokens[retry] = policy.ID
	return policy, nil
}

func (p *fakeProvider) VolumeBackupPolicyAssignment(_ context.Context, volumeID string) (string, error) {
	return p.backupPolicyAssignments[volumeID], nil
}

func (p *fakeProvider) AssignVolumeBackupPolicy(_ context.Context, volumeID, policyID string) error {
	if p.backupPolicyAssignments == nil {
		p.backupPolicyAssignments = make(map[string]string)
	}
	// Like OCI, a new assignment replaces the volume's current one.
	p.backupPolicyAssignments[volumeID] = policyID
	return nil
}

type fakeProvider struct {
	config                       RegionConfig
	instances                    map[string]CloudInstance
	launchRetryTokens            map[string]string
	launchRequests               []LaunchRequest
	launchObservationMutation    func(*CloudInstance)
	launchErrorBeforeCreate      error
	devices                      map[string][]CloudDevice
	volumes                      map[string]CloudVolume
	bootVolumes                  map[string]CloudBootVolume
	volumeRetryTokens            map[string]string
	attachments                  map[string]CloudAttachment
	attachRetryTokens            map[string]string
	attachmentListErr            error
	afterAttach                  func(*fakeProvider, string)
	launches                     int
	launchCalls                  int
	launchErrorAfterCreate       error
	volumeCreates                int
	volumeCreateCalls            int
	volumeCreateErrorAfterCreate error
	volumeRetryReplayError       error
	afterVolumeCreate            func()
	attachCalls                  int
	deviceListCalls              int
	attachErrorAfterCreate       error
	attachReplayError            error
	terminations                 int
	backupPolicies               []CloudBackupPolicy
	backupPolicyRetryTokens      map[string]string
	backupPolicyAssignments      map[string]string
	backupPolicyCreates          int
	volumeCreateRequests         []VolumeCreateRequest
	volumeBackups                []CloudVolumeBackup
}

func newFakeProvider(config RegionConfig) *fakeProvider {
	return &fakeProvider{
		config: config, instances: make(map[string]CloudInstance), launchRetryTokens: make(map[string]string),
		devices: make(map[string][]CloudDevice),
		volumes: make(map[string]CloudVolume), volumeRetryTokens: make(map[string]string),
		bootVolumes: make(map[string]CloudBootVolume),
		attachments: make(map[string]CloudAttachment), attachRetryTokens: make(map[string]string),
	}
}

func (p *fakeProvider) ListInstances(_ context.Context, compartmentID string) ([]CloudInstance, error) {
	if compartmentID != p.config.CompartmentID {
		return nil, ErrForeignResource
	}
	instances := make([]CloudInstance, 0, len(p.instances))
	for _, instance := range p.instances {
		instances = append(instances, cloneCloudInstance(instance))
	}
	return instances, nil
}

func (p *fakeProvider) GetInstance(_ context.Context, id string) (CloudInstance, error) {
	instance, ok := p.instances[id]
	if !ok {
		return CloudInstance{}, fakeNotFound{}
	}
	return cloneCloudInstance(instance), nil
}

func (p *fakeProvider) LaunchInstance(_ context.Context, request LaunchRequest) (CloudInstance, error) {
	p.launchCalls++
	p.launchRequests = append(p.launchRequests, request)
	if p.launchErrorBeforeCreate != nil {
		return CloudInstance{}, p.launchErrorBeforeCreate
	}
	if id, exists := p.launchRetryTokens[request.RetryToken]; exists {
		return cloneCloudInstance(p.instances[id]), nil
	}
	p.launches++
	id := fmt.Sprintf("ocid1.instance.new-%d", p.launches)
	instance := CloudInstance{
		ID: id, PrivateIP: request.PrivateIP, CompartmentID: p.config.CompartmentID, AvailabilityDomain: p.config.AvailabilityDomain,
		FaultDomain: request.FaultDomain, Shape: request.Shape, Ocpus: new(float32(request.WholeOCPUs)),
		MemoryInGBs: new(float32(request.MemoryInGBs)), LifecycleState: "PROVISIONING", ETag: "e1", ImageID: request.ImageID,
		ConsistentVolumeNamingEnabled: new(true),
		Metadata:                      map[string]string{hostboot.MetadataKey: request.BootDescriptor, "terrascale_host_node": request.Node},
		FreeformTags:                  cloneStringMap(request.FreeformTags),
	}
	if p.launchObservationMutation != nil {
		p.launchObservationMutation(&instance)
	}
	p.instances[id] = instance
	p.launchRetryTokens[request.RetryToken] = id
	launchErr := p.launchErrorAfterCreate
	p.launchErrorAfterCreate = nil
	return cloneCloudInstance(instance), launchErr
}

func (p *fakeProvider) UpdateInstanceTags(_ context.Context, id, etag string, tags map[string]string) (CloudInstance, error) {
	instance, ok := p.instances[id]
	if !ok {
		return CloudInstance{}, fakeNotFound{}
	}
	if instance.ETag != etag {
		return CloudInstance{}, ErrStaleETag
	}
	instance.FreeformTags = cloneStringMap(tags)
	instance.ETag = etag + "-next"
	p.instances[id] = instance
	return cloneCloudInstance(instance), nil
}

func (p *fakeProvider) TerminateInstance(_ context.Context, id, etag string) error {
	instance, ok := p.instances[id]
	if !ok {
		return fakeNotFound{}
	}
	if instance.ETag != etag {
		return ErrStaleETag
	}
	instance.LifecycleState = "TERMINATING"
	instance.ETag = etag + "-term"
	p.instances[id] = instance
	p.terminations++
	return nil
}

func (p *fakeProvider) TerminateTerminalInstance(ctx context.Context, id, etag string) error {
	return p.TerminateInstance(ctx, id, etag)
}

func (p *fakeProvider) GetAttachedBootVolume(_ context.Context, instanceID string) (CloudBootVolume, error) {
	instance, ok := p.instances[instanceID]
	if !ok {
		return CloudBootVolume{}, fakeNotFound{}
	}
	id := "ocid1.bootvolume." + strings.TrimPrefix(instanceID, "ocid1.instance.")
	if boot, ok := p.bootVolumes[id]; ok {
		return boot, nil
	}
	boot := CloudBootVolume{ID: id, CompartmentID: p.config.CompartmentID,
		AvailabilityDomain: p.config.AvailabilityDomain, ImageID: instance.ImageID,
		SizeGB: int64(p.config.BootVolumeGB), VPUsPerGB: int64(p.config.BootVolumeVPUsPerGB),
		LifecycleState: "AVAILABLE", ETag: "boot-etag"}
	p.bootVolumes[id] = boot
	return boot, nil
}

func (p *fakeProvider) GetBootVolume(_ context.Context, id string) (CloudBootVolume, error) {
	boot, ok := p.bootVolumes[id]
	if !ok {
		return CloudBootVolume{}, fakeNotFound{}
	}
	return boot, nil
}

func (p *fakeProvider) ListBootVolumeAttachments(_ context.Context, id string) ([]CloudBootAttachment, error) {
	for instanceID, instance := range p.instances {
		if id == "ocid1.bootvolume."+strings.TrimPrefix(instanceID, "ocid1.instance.") {
			if instance.LifecycleState == "TERMINATED" {
				return nil, nil
			}
			return []CloudBootAttachment{{InstanceID: instanceID, BootVolumeID: id, LifecycleState: "ATTACHED"}}, nil
		}
	}
	return nil, nil
}

func (p *fakeProvider) DeleteBootVolume(_ context.Context, id, etag string) error {
	boot, ok := p.bootVolumes[id]
	if !ok {
		return fakeNotFound{}
	}
	if boot.ETag != etag {
		return ErrStaleETag
	}
	delete(p.bootVolumes, id)
	return nil
}

func (p *fakeProvider) DeleteVolume(_ context.Context, id, etag string) error {
	volume, ok := p.volumes[id]
	if !ok {
		return fakeNotFound{}
	}
	if volume.ETag != etag {
		return ErrStaleETag
	}
	delete(p.volumes, id)
	return nil
}

func (p *fakeProvider) ListVolumeAttachments(_ context.Context, compartmentID, instanceID string) ([]CloudAttachment, error) {
	if compartmentID != p.config.CompartmentID {
		return nil, ErrForeignResource
	}
	if p.attachmentListErr != nil {
		err := p.attachmentListErr
		p.attachmentListErr = nil
		return nil, err
	}
	var attachments []CloudAttachment
	for _, attachment := range p.attachments {
		if instanceID == "" || attachment.InstanceID == instanceID {
			attachments = append(attachments, attachment)
		}
	}
	return attachments, nil
}

func (p *fakeProvider) ListInstanceDevices(_ context.Context, instanceID string) ([]CloudDevice, error) {
	p.deviceListCalls++
	devices, exists := p.devices[instanceID]
	if exists {
		return cloneCloudDevices(devices), nil
	}
	available := true
	return []CloudDevice{
		{Name: "/dev/oracleoci/oraclevdb", IsAvailable: &available},
		{Name: "/dev/oracleoci/oraclevdc", IsAvailable: &available},
	}, nil
}

func (p *fakeProvider) GetVolumeAttachment(_ context.Context, id string) (CloudAttachment, error) {
	attachment, ok := p.attachments[id]
	if !ok {
		return CloudAttachment{}, fakeNotFound{}
	}
	return attachment, nil
}

func (p *fakeProvider) AttachVolume(_ context.Context, request CloudVolumeAttachRequest) (CloudAttachment, error) {
	if id, exists := p.attachRetryTokens[request.RetryToken]; exists {
		return p.attachments[id], p.attachReplayError
	}
	p.attachCalls++
	readOnly, shareable, encryption := request.IsReadOnly, request.IsShareable, request.IsPvEncryptionInTransitEnabled
	attachment := CloudAttachment{
		ID: fmt.Sprintf("attachment-%d", p.attachCalls), VolumeID: request.VolumeID,
		InstanceID: request.InstanceID, LifecycleState: "ATTACHED", ETag: "a1", Device: request.Device,
		IsReadOnly: &readOnly, IsShareable: &shareable, IsPvEncryptionInTransitEnabled: &encryption,
	}
	// Like OCI, the response describes the attachment while it is ATTACHING,
	// under an ETag that changes once it settles.
	response := attachment
	response.LifecycleState, response.ETag = "ATTACHING", "a0"
	p.attachments[attachment.ID] = attachment
	p.attachRetryTokens[request.RetryToken] = attachment.ID
	if p.afterAttach != nil {
		p.afterAttach(p, attachment.ID)
		p.afterAttach = nil
	}
	attachErr := p.attachErrorAfterCreate
	p.attachErrorAfterCreate = nil
	return response, attachErr
}

func (p *fakeProvider) DetachVolume(_ context.Context, id, etag string) error {
	attachment, ok := p.attachments[id]
	if !ok {
		return fakeNotFound{}
	}
	if attachment.ETag != etag {
		return ErrStaleETag
	}
	delete(p.attachments, id)
	return nil
}

func (p *fakeProvider) GetVolume(_ context.Context, id string) (CloudVolume, error) {
	volume, ok := p.volumes[id]
	if !ok {
		return CloudVolume{}, fakeNotFound{}
	}
	volume.FreeformTags = cloneStringMap(volume.FreeformTags)
	return volume, nil
}

func (p *fakeProvider) ListVolumes(_ context.Context, compartmentID, availabilityDomain string) ([]CloudVolume, error) {
	if compartmentID != p.config.CompartmentID || availabilityDomain != p.config.AvailabilityDomain {
		return nil, ErrForeignResource
	}
	var volumes []CloudVolume
	for _, volume := range p.volumes {
		if volume.AvailabilityDomain == availabilityDomain {
			volume.FreeformTags = cloneStringMap(volume.FreeformTags)
			volumes = append(volumes, volume)
		}
	}
	return volumes, nil
}

func (p *fakeProvider) CreateVolume(_ context.Context, request VolumeCreateRequest, tags map[string]string, retry string) (CloudVolume, error) {
	p.volumeCreateCalls++
	if id, exists := p.volumeRetryTokens[retry]; exists {
		return p.volumes[id], p.volumeRetryReplayError
	}
	p.volumeCreates++
	p.volumeCreateRequests = append(p.volumeCreateRequests, request)
	id := fmt.Sprintf("ocid1.volume.created-%d", p.volumeCreates)
	volume := CloudVolume{
		ID: id, CompartmentID: p.config.CompartmentID, AvailabilityDomain: request.AvailabilityDomain,
		SizeGB: request.SizeGB, VPUsPerGB: int64(p.config.DataVolumeVPUsPerGB),
		LifecycleState: "PROVISIONING", ETag: "volume-etag", FreeformTags: cloneStringMap(tags),
	}
	p.volumes[id] = volume
	p.volumeRetryTokens[retry] = id
	createErr := p.volumeCreateErrorAfterCreate
	p.volumeCreateErrorAfterCreate = nil
	if p.afterVolumeCreate != nil {
		p.afterVolumeCreate()
	}
	volume.FreeformTags = cloneStringMap(volume.FreeformTags)
	return volume, createErr
}

func newMemberVolumes(config MemberVolumeConfig, provider Provider) (*MemberVolumes, error) {
	regionConfig, err := config.regionConfig()
	if err != nil {
		return nil, err
	}
	return &MemberVolumes{fleet: memberVolumeFleet(regionConfig, provider), restoreSettle: restoreSettleTimeout}, nil
}

// memberVolumeFleet reuses the fleet's volume and attachment reads. It has no
// journal, fencer or image verifier, so only the member volume methods below
// may use it.
func memberVolumeFleet(config RegionConfig, provider Provider) *fleet {
	return &fleet{config: config, provider: provider, now: time.Now, attachmentSettle: attachmentSettleTimeout}
}

// regionConfig scopes the reused fleet reads and tags to the cell: names are
// static, so the volumes belong to the cell and carry generation 1.
func (config MemberVolumeConfig) regionConfig() (RegionConfig, error) {
	ociRegion, err := config.Region.OCIRegion()
	if err != nil {
		return RegionConfig{}, err
	}
	cell, err := naming.RegionCell(string(config.Region)).Name()
	if err != nil {
		return RegionConfig{}, err
	}
	if config.CompartmentID == "" || config.AvailabilityDomain == "" || config.VPUsPerGB%10 != 0 || config.VPUsPerGB > 120 {
		return RegionConfig{}, errors.New("member volumes need a compartment, an availability domain and a VPUs per GB tier of 0 to 120 in steps of 10")
	}
	return RegionConfig{
		Region: config.Region, Generation: 1, Endpoint: "https://iaas." + ociRegion + ".oraclecloud.com",
		CompartmentID: config.CompartmentID, AvailabilityDomain: config.AvailabilityDomain,
		DataVolumeVPUsPerGB: config.VPUsPerGB, MaxDataVolumeGB: maxMemberVolumeGB, Owner: cell,
	}, nil
}

func (v *MemberVolumes) Ensure(ctx context.Context, request MemberVolumeRequest) (Attachment, error) {
	member, instanceID, sizeGB := request.Member, request.InstanceID, request.SizeGB
	name, err := v.volumeName(member)
	if err != nil {
		return Attachment{}, err
	}
	if sizeGB < minRetainedVolumeSizeGB || sizeGB > maxMemberVolumeGB {
		return Attachment{}, fmt.Errorf("member data volume size must be %d to %d GB", minRetainedVolumeSizeGB, maxMemberVolumeGB)
	}
	f := v.fleet
	instance, err := f.provider.GetInstance(ctx, instanceID)
	if err != nil {
		return Attachment{}, err
	}
	if instance.ID != instanceID || instance.DisplayName != member ||
		instance.CompartmentID != f.config.CompartmentID || instance.AvailabilityDomain != f.config.AvailabilityDomain {
		return Attachment{}, fmt.Errorf("%w: instance %s is not member %s in the cell's compartment and availability domain", ErrForeignResource, instanceID, member)
	}
	if instance.LifecycleState != "RUNNING" {
		return Attachment{}, fmt.Errorf("instance %s is %s; its data volume attaches once it runs", instanceID, instance.LifecycleState)
	}
	if instance.ConsistentVolumeNamingEnabled == nil || !*instance.ConsistentVolumeNamingEnabled {
		return Attachment{}, fmt.Errorf("instance %s has no consistent volume naming for %s", instanceID, MemberVolumeDevice)
	}
	volume, err := v.ensureVolume(ctx, name, sizeGB, request.VolumeID)
	if err != nil {
		return Attachment{}, err
	}
	if err := v.ensureBackupPolicy(ctx, volume.ID); err != nil {
		return Attachment{}, fmt.Errorf("data volume %s backup policy: %w", name, err)
	}
	return v.attach(ctx, name, volume.ID, instanceID, MemberVolumeDevice)
}

// Resize requires the member's exact recorded volume ID and grows it online
// to sizeGB. A size at or below the
// current one changes nothing. The member's host grows the filesystem once
// it sees the larger device.
func (v *MemberVolumes) Resize(ctx context.Context, member, recordedID string, sizeGB int64) (RetainedVolume, error) {
	name, err := v.volumeName(member)
	if err != nil {
		return RetainedVolume{}, err
	}
	if sizeGB < minRetainedVolumeSizeGB || sizeGB > maxMemberVolumeGB {
		return RetainedVolume{}, fmt.Errorf("member data volume size must be %d to %d GB", minRetainedVolumeSizeGB, maxMemberVolumeGB)
	}
	if recordedID == "" {
		return RetainedVolume{}, errors.New("member data volume resize requires its recorded volume ID")
	}
	f := v.fleet
	updater, ok := f.provider.(VolumeUpdater)
	if !ok {
		return RetainedVolume{}, ErrVolumeResizeUnsupported
	}
	cloud, identity, found, err := f.findVolumeByCreateKey(ctx, memberVolumeCreateKey(name))
	if err != nil {
		return RetainedVolume{}, err
	}
	if !found {
		return RetainedVolume{}, fmt.Errorf("member %s has no data volume %s", member, name)
	}
	if cloud.ID != recordedID {
		return RetainedVolume{}, fmt.Errorf("%w: data volume %s is %s, not the recorded %s", ErrForeignResource, name, cloud.ID, recordedID)
	}
	if cloud.SizeGB >= sizeGB {
		return retainedVolumeFromCloud(cloud, identity), nil
	}
	if cloud.LifecycleState != "AVAILABLE" {
		return RetainedVolume{}, fmt.Errorf("data volume %s is %s; it grows only while AVAILABLE", name, cloud.LifecycleState)
	}
	if cloud.ETag == "" {
		return RetainedVolume{}, ErrStaleETag
	}
	tags := maps.Clone(cloud.FreeformTags)
	tags[tagVolumeSize] = fmt.Sprint(sizeGB)
	_, updateErr := updater.UpdateVolumeSize(ctx, cloud.ID, cloud.ETag, sizeGB, tags)
	grown, err := v.awaitVolume(ctx, cloud.ID, sizeGB)
	if err != nil {
		return RetainedVolume{}, errors.Join(ErrOutcomeUnknown, updateErr, err)
	}
	_, identity, err = f.reobserveVolume(ctx, grown.ID)
	if err != nil {
		return RetainedVolume{}, err
	}
	return retainedVolumeFromCloud(grown, identity), nil
}

func (v *MemberVolumes) volumeName(member string) (string, error) {
	if !v.fleet.memberName(member, false) {
		return "", fmt.Errorf("%q is not a member name of this cell", member)
	}
	return naming.Data(member)
}

func (v *MemberVolumes) ensureVolume(ctx context.Context, name string, sizeGB int64, recorded string) (CloudVolume, error) {
	f := v.fleet
	cloud, _, found, err := f.findVolumeByCreateKey(ctx, memberVolumeCreateKey(name))
	if err != nil {
		return CloudVolume{}, err
	}
	switch {
	case recorded != "" && !found:
		return CloudVolume{}, fmt.Errorf("recorded data volume %s (%s) is missing; restore it from a backup instead of creating an empty one", name, recorded)
	case recorded != "" && cloud.ID != recorded:
		return CloudVolume{}, fmt.Errorf("%w: data volume %s is %s, not the recorded %s", ErrForeignResource, name, cloud.ID, recorded)
	case !found:
		request := VolumeCreateRequest{Name: name, CreateKey: memberVolumeCreateKey(name), SizeGB: sizeGB, AvailabilityDomain: f.config.AvailabilityDomain}
		// Stable within one incarnation, fresh after retirement: a lost create
		// response replays, but a reused name cannot replay a retired volume.
		retry, err := v.memberCreateToken(ctx, name)
		if err != nil {
			return CloudVolume{}, err
		}
		_, createErr := f.provider.CreateVolume(ctx, request, volumeTags(f.config, request), retry)
		cloud, _, found, err = f.findVolumeByCreateKey(ctx, memberVolumeCreateKey(name))
		if err != nil || !found {
			return CloudVolume{}, errors.Join(ErrOutcomeUnknown, createErr, err,
				fmt.Errorf("data volume %s was not observed after its create", name))
		}
	}
	return v.awaitVolume(ctx, cloud.ID, 0)
}

func (v *MemberVolumes) memberCreateToken(ctx context.Context, name string) (string, error) {
	f := v.fleet
	volumes, err := f.provider.ListVolumes(ctx, f.config.CompartmentID, f.config.AvailabilityDomain)
	if err != nil {
		return "", err
	}
	var retired []string
	for _, listed := range volumes {
		if listed.FreeformTags[tagRetiredNode]+"-data" != name {
			continue
		}
		volume, _, err := f.reobserveVolumeResource(ctx, listed.ID, resourceMemberRetiredData)
		if err != nil {
			return "", err
		}
		if _, err := time.Parse(time.RFC3339Nano, volume.FreeformTags[tagRetiredAt]); err != nil ||
			volume.FreeformTags[tagCreateKey] != retiredMemberCreateKey(volume.ID) || volume.FreeformTags[tagRetiredInstance] == "" {
			return "", fmt.Errorf("%w: volume %s has incomplete retirement tags", ErrForeignResource, volume.ID)
		}
		retired = append(retired, volume.ID)
	}
	slices.Sort(retired)
	return retryToken(strings.Join(append([]string{f.config.Owner, string(f.config.Region), name}, retired...), ":")), nil
}

func memberVolumeCreateKey(name string) string { return entityid.Derive("member-volume", name) }

func retiredMemberCreateKey(volumeID string) string {
	return entityid.Derive("retired-volume", volumeID)
}

func (v *MemberVolumes) awaitVolume(ctx context.Context, volumeID string, sizeGB int64) (CloudVolume, error) {
	f := v.fleet
	settleCtx, cancel := context.WithTimeout(ctx, f.attachmentSettle)
	defer cancel()
	for {
		cloud, _, err := f.reobserveVolume(settleCtx, volumeID)
		if err != nil {
			return CloudVolume{}, err
		}
		switch cloud.LifecycleState {
		case "AVAILABLE":
			if cloud.SizeGB >= sizeGB {
				return cloud, nil
			}
		case "PROVISIONING", "RESTORING":
		default:
			return CloudVolume{}, fmt.Errorf("data volume %s is %s; restore it from a backup or remove it before a new one is created", volumeID, cloud.LifecycleState)
		}
		select {
		case <-settleCtx.Done():
			return CloudVolume{}, fmt.Errorf("data volume %s is %s at %d GB: %w", volumeID, cloud.LifecycleState, cloud.SizeGB, settleCtx.Err())
		case <-time.After(attachmentSettlePoll):
		}
	}
}

func (v *MemberVolumes) attach(ctx context.Context, name, volumeID, instanceID, device string) (Attachment, error) {
	f := v.fleet
	records, err := f.findVolumeAttachments(ctx, volumeID)
	if err != nil {
		return Attachment{}, err
	}
	live := liveAttachments(records)
	switch {
	case len(live) > 1:
		return Attachment{}, fmt.Errorf("%w: data volume %s has %d live attachments", ErrAttachmentRecoveryHold, name, len(live))
	case len(live) == 1 && live[0].InstanceID != instanceID:
		return Attachment{}, fmt.Errorf("%w: data volume %s is %s on instance %s; it moves only after OCI detaches it from that instance",
			ErrRetainedVolumeInUse, name, live[0].LifecycleState, live[0].InstanceID)
	case len(live) == 1:
		return f.awaitAttached(ctx, live[0].ID, volumeID, instanceID, device)
	}
	devices, err := f.provider.ListInstanceDevices(ctx, instanceID)
	if err != nil {
		return Attachment{}, fmt.Errorf("list OCI instance devices: %w", err)
	}
	if !slices.ContainsFunc(devices, func(candidate CloudDevice) bool {
		return candidate.Name == device && candidate.IsAvailable != nil && *candidate.IsAvailable
	}) {
		return Attachment{}, fmt.Errorf("instance %s has no free %s for data volume %s", instanceID, device, name)
	}
	_, attachErr := f.provider.AttachVolume(ctx, CloudVolumeAttachRequest{
		VolumeID: volumeID, InstanceID: instanceID,
		RetryToken: retryToken(strings.Join([]string{f.config.Owner, string(f.config.Region), name, volumeID, instanceID}, ":")),
		Device:     device, IsReadOnly: retainedVolumeReadOnly, IsShareable: retainedVolumeShareable,
		IsPvEncryptionInTransitEnabled: retainedVolumeEncryptionInTransit,
	})
	records, err = f.findVolumeAttachments(ctx, volumeID)
	live = liveAttachments(records)
	if err != nil || len(live) != 1 || live[0].InstanceID != instanceID {
		return Attachment{}, errors.Join(ErrOutcomeUnknown, attachErr, err,
			fmt.Errorf("data volume %s attachment to %s was not observed", name, instanceID))
	}
	return f.awaitAttached(ctx, live[0].ID, volumeID, instanceID, device)
}

// ensureBackupPolicy assigns the cell's member backup policy, creating it on
// first use, to volumeID. A volume that already carries another policy, or a
// policy of that name whose schedules or tags differ, holds instead of being
// changed.
func (v *MemberVolumes) ensureBackupPolicy(ctx context.Context, volumeID string) error {
	f := v.fleet
	policies, ok := f.provider.(BackupPolicyProvider)
	if !ok {
		return errors.New("OCI provider cannot manage volume backup policies")
	}
	name := f.config.Owner + "-db-data"
	policy, found, err := v.findBackupPolicy(ctx, policies, name)
	if err != nil {
		return err
	}
	if !found {
		tags := map[string]string{tagManagedBy: managedByValue, tagOwner: f.config.Owner,
			tagRegion: string(f.config.Region), tagResource: resourceMemberBackupPolicy}
		retry := retryToken(strings.Join([]string{f.config.Owner, string(f.config.Region), name}, ":"))
		_, createErr := policies.CreateVolumeBackupPolicy(ctx, name, MemberBackupSchedules, tags, retry)
		if policy, found, err = v.findBackupPolicy(ctx, policies, name); err != nil || !found {
			return errors.Join(ErrOutcomeUnknown, createErr, err, fmt.Errorf("backup policy %s was not observed after its create", name))
		}
	}
	current, err := policies.VolumeBackupPolicyAssignment(ctx, volumeID)
	if err != nil || current == policy.ID {
		return err
	}
	if current != "" {
		return fmt.Errorf("%w: volume %s carries backup policy %s, not %s", ErrForeignResource, volumeID, current, policy.ID)
	}
	assignErr := policies.AssignVolumeBackupPolicy(ctx, volumeID, policy.ID)
	if current, err = policies.VolumeBackupPolicyAssignment(ctx, volumeID); err != nil || current != policy.ID {
		return errors.Join(ErrOutcomeUnknown, assignErr, err, fmt.Errorf("backup policy %s is not assigned to volume %s", policy.ID, volumeID))
	}
	return nil
}

func (v *MemberVolumes) findBackupPolicy(ctx context.Context, policies BackupPolicyProvider, name string) (CloudBackupPolicy, bool, error) {
	listed, err := policies.ListVolumeBackupPolicies(ctx)
	if err != nil {
		return CloudBackupPolicy{}, false, err
	}
	var matches []CloudBackupPolicy
	for _, policy := range listed {
		if policy.DisplayName == name {
			matches = append(matches, policy)
		}
	}
	switch {
	case len(matches) == 0:
		return CloudBackupPolicy{}, false, nil
	case len(matches) > 1:
		return CloudBackupPolicy{}, false, fmt.Errorf("%w: backup policy %s", ErrDuplicateCreateKey, name)
	}
	policy, f := matches[0], v.fleet
	if policy.FreeformTags[tagManagedBy] != managedByValue || policy.FreeformTags[tagOwner] != f.config.Owner ||
		policy.FreeformTags[tagResource] != resourceMemberBackupPolicy || len(policy.Schedules) != len(MemberBackupSchedules) ||
		slices.ContainsFunc(MemberBackupSchedules, func(want BackupSchedule) bool { return !slices.Contains(policy.Schedules, want) }) {
		return CloudBackupPolicy{}, false, fmt.Errorf("%w: backup policy %s has other tags or schedules than the member backup policy", ErrForeignResource, name)
	}
	return policy, true, nil
}

func (f *fleet) awaitAttached(ctx context.Context, attachmentID, volumeID, instanceID, expectedDevice string) (Attachment, error) {
	settleCtx, cancel := context.WithTimeout(ctx, f.attachmentSettle)
	defer cancel()
	for {
		cloud, err := f.provider.GetVolumeAttachment(settleCtx, attachmentID)
		if err != nil {
			return Attachment{}, err
		}
		if cloud.LifecycleState != "ATTACHING" {
			return f.reobserveAttachment(ctx, attachmentID, volumeID, instanceID, expectedDevice)
		}
		select {
		case <-settleCtx.Done():
			return Attachment{}, fmt.Errorf("OCI volume attachment %s is still ATTACHING: %w", attachmentID, settleCtx.Err())
		case <-time.After(attachmentSettlePoll):
		}
	}
}

func (f *fleet) reobserveAttachment(ctx context.Context, attachmentID, volumeID, instanceID, expectedDevice string) (Attachment, error) {
	cloud, err := f.provider.GetVolumeAttachment(ctx, attachmentID)
	if err != nil {
		return Attachment{}, err
	}
	if cloud.ID != attachmentID || cloud.VolumeID != volumeID || cloud.InstanceID != instanceID || cloud.ETag == "" ||
		cloud.LifecycleState != "ATTACHED" || !validDevicePath(cloud.Device) ||
		expectedDevice != "" && cloud.Device != expectedDevice ||
		cloud.IsReadOnly == nil || *cloud.IsReadOnly != retainedVolumeReadOnly ||
		cloud.IsShareable == nil || *cloud.IsShareable != retainedVolumeShareable ||
		cloud.IsPvEncryptionInTransitEnabled == nil || *cloud.IsPvEncryptionInTransitEnabled != retainedVolumeEncryptionInTransit {
		return Attachment{}, fmt.Errorf("%w: OCI volume attachment scope or state changed", ErrForeignResource)
	}
	return Attachment{
		ID: cloud.ID, VolumeID: cloud.VolumeID, InstanceID: cloud.InstanceID,
		ETag: cloud.ETag, State: cloud.LifecycleState, Device: cloud.Device,
		IsReadOnly: *cloud.IsReadOnly, IsShareable: *cloud.IsShareable,
		IsPvEncryptionInTransitEnabled: *cloud.IsPvEncryptionInTransitEnabled,
	}, nil
}

func validDevicePath(value string) bool {
	return len(value) > len("/dev/") && len(value) <= 255 && strings.HasPrefix(value, "/dev/") &&
		path.Clean(value) == value && strings.TrimSpace(value) == value &&
		!strings.ContainsAny(value, " \t\r\n\x00")
}

// findVolumeAttachments lists every attachment record of one volume. OCI
// filters by VolumeId server-side when the provider supports it; the result
// is still filtered here so a provider bug cannot widen the scope.
func (f *fleet) findVolumeAttachments(ctx context.Context, volumeID string) ([]CloudAttachment, error) {
	var attachments []CloudAttachment
	var err error
	if lister, ok := f.provider.(VolumeAttachmentLister); ok {
		attachments, err = lister.ListVolumeAttachmentsByVolume(ctx, f.config.CompartmentID, f.config.AvailabilityDomain, volumeID)
	} else {
		attachments, err = f.provider.ListVolumeAttachments(ctx, f.config.CompartmentID, "")
	}
	if err != nil {
		return nil, err
	}
	var found []CloudAttachment
	for _, attachment := range attachments {
		if attachment.VolumeID == volumeID {
			found = append(found, attachment)
		}
	}
	return found, nil
}

func (f *fleet) ownedVolume(ctx context.Context, volumeID string) (CloudVolume, error) {
	volume, identity, err := f.reobserveVolume(ctx, volumeID)
	if err != nil {
		return CloudVolume{}, err
	}
	owned, err := f.journal.IsOwnedVolume(ctx, identity)
	if err != nil {
		return CloudVolume{}, fmt.Errorf("read OCI retained volume ownership journal: %w", err)
	}
	if !owned {
		return CloudVolume{}, fmt.Errorf("%w: %s", ErrRetainedVolumeUnknown, volumeID)
	}
	return volume, nil
}

func (f *fleet) findVolumeByCreateKey(ctx context.Context, createKey string) (CloudVolume, ResourceIdentity, bool, error) {
	volumes, err := f.provider.ListVolumes(ctx, f.config.CompartmentID, f.config.AvailabilityDomain)
	if err != nil {
		return CloudVolume{}, ResourceIdentity{}, false, err
	}
	var ids []string
	for _, volume := range volumes {
		if volume.FreeformTags[tagCreateKey] == createKey && !f.terminatedForeign(volume.FreeformTags, volume.LifecycleState) {
			ids = append(ids, volume.ID)
		}
	}
	if len(ids) > 1 {
		return CloudVolume{}, ResourceIdentity{}, false, ErrDuplicateCreateKey
	}
	if len(ids) == 0 {
		return CloudVolume{}, ResourceIdentity{}, false, nil
	}
	volume, identity, err := f.reobserveVolume(ctx, ids[0])
	if err != nil {
		return CloudVolume{}, ResourceIdentity{}, false, err
	}
	if identity.CreateKey != createKey {
		return CloudVolume{}, ResourceIdentity{}, false, ErrForeignResource
	}
	return volume, identity, true, nil
}

func (f *fleet) reobserveVolume(ctx context.Context, volumeID string) (CloudVolume, ResourceIdentity, error) {
	return f.reobserveVolumeResource(ctx, volumeID, resourceMemberData)
}

// reobserveVolumeResource checks the same regional volume pins for explicitly
// selected resource kinds. Normal fleet reads accept only member data.
func (f *fleet) reobserveVolumeResource(ctx context.Context, volumeID string, resources ...string) (CloudVolume, ResourceIdentity, error) {
	volume, err := f.provider.GetVolume(ctx, volumeID)
	if err != nil {
		return CloudVolume{}, ResourceIdentity{}, err
	}
	tags := volume.FreeformTags
	createKey := tags[tagCreateKey]
	identity := ResourceIdentity{
		ID: volume.ID, Region: f.config.Region, Generation: f.config.Generation,
		Owner: f.config.Owner, CreateKey: createKey,
		AvailabilityDomain: volume.AvailabilityDomain, SizeGB: volume.SizeGB,
	}
	if volume.ID != volumeID || volume.CompartmentID != f.config.CompartmentID ||
		volume.AvailabilityDomain != f.config.AvailabilityDomain || volume.SizeGB < minRetainedVolumeSizeGB ||
		volume.SizeGB > f.config.MaxDataVolumeGB ||
		volume.VPUsPerGB != int64(f.config.DataVolumeVPUsPerGB) ||
		tags[tagManagedBy] != managedByValue || tags[tagOwner] != f.config.Owner ||
		tags[tagRegion] != string(f.config.Region) || tags[tagGeneration] != fmt.Sprint(f.config.Generation) ||
		!slices.Contains(resources, tags[tagResource]) || tags[tagVolumeSize] != fmt.Sprint(volume.SizeGB) ||
		!validCreateKey(createKey) || !validVolumeLifecycleState(volume.LifecycleState) {
		return CloudVolume{}, ResourceIdentity{}, fmt.Errorf("%w: retained volume %s has missing or mismatched scope tags, size, domain, or state", ErrForeignResource, volumeID)
	}
	return volume, identity, nil
}

// attachment seams to the shared fake provider.
type resizeProvider struct {
	*fakeProvider
	updates            int
	updateErr          error
	updateApplies      bool
	volumeAttachLists  int
	compartmentListing int
}

func (p *resizeProvider) UpdateVolumeSize(_ context.Context, id, etag string, sizeGB int64, tags map[string]string) (CloudVolume, error) {
	p.updates++
	volume, ok := p.volumes[id]
	if !ok {
		return CloudVolume{}, fakeNotFound{}
	}
	if volume.ETag != etag {
		return CloudVolume{}, ErrStaleETag
	}
	if p.updateErr != nil && !p.updateApplies {
		return CloudVolume{}, p.updateErr
	}
	volume.SizeGB = sizeGB
	volume.FreeformTags = maps.Clone(tags)
	volume.ETag = fmt.Sprintf("%s-resized-%d", etag, sizeGB)
	p.volumes[id] = volume
	return volume, p.updateErr
}

func (p *resizeProvider) ListVolumeAttachments(ctx context.Context, compartmentID, instanceID string) ([]CloudAttachment, error) {
	if instanceID == "" {
		p.compartmentListing++
	}
	return p.fakeProvider.ListVolumeAttachments(ctx, compartmentID, instanceID)
}

func (p *resizeProvider) ListVolumeAttachmentsByVolume(_ context.Context, compartmentID, availabilityDomain, volumeID string) ([]CloudAttachment, error) {
	if compartmentID != p.config.CompartmentID || availabilityDomain != p.config.AvailabilityDomain {
		return nil, ErrForeignResource
	}
	p.volumeAttachLists++
	var found []CloudAttachment
	for _, attachment := range p.attachments {
		if attachment.VolumeID == volumeID {
			found = append(found, attachment)
		}
	}
	// A foreign record proves the fleet still filters client-side.
	found = append(found, CloudAttachment{ID: "foreign", VolumeID: "ocid1.volume.other"})
	return found, nil
}

func (p *fakeProvider) ListVolumeBackups(_ context.Context, volumeID string) ([]CloudVolumeBackup, error) {
	var backups []CloudVolumeBackup
	for _, backup := range p.volumeBackups {
		if backup.VolumeID == volumeID {
			backups = append(backups, backup)
		}
	}
	return backups, nil
}

func (p *fakeProvider) GetVolumeBackup(_ context.Context, id string) (CloudVolumeBackup, error) {
	for _, backup := range p.volumeBackups {
		if backup.ID == id {
			return backup, nil
		}
	}
	return CloudVolumeBackup{}, fakeNotFound{}
}

func (v *MemberVolumes) Restore(ctx context.Context, request RestoreRequest) (RestoredVolume, error) {
	name, err := v.volumeName(request.Member)
	if err != nil {
		return RestoredVolume{}, err
	}
	f := v.fleet
	backups, ok := f.provider.(volumeBackupReader)
	if !ok {
		return RestoredVolume{}, errors.New("OCI provider cannot read volume backups")
	}
	if err := v.requireScratchInstance(ctx, request.ScratchInstanceID); err != nil {
		return RestoredVolume{}, err
	}
	backup, err := v.selectBackup(ctx, backups, name, request.BackupID, request.SourceVolumeID)
	if err != nil {
		return RestoredVolume{}, err
	}
	restoreName := "restore-" + name
	createKey := entityid.Derive("restore-volume", f.config.Owner, request.Member, backup.ID)
	volume, found, err := v.findRestoredVolume(ctx, createKey)
	if err != nil {
		return RestoredVolume{}, err
	}
	if err := v.requireOnlyAttachment(ctx, request.ScratchInstanceID, volume.ID, false); err != nil {
		return RestoredVolume{}, err
	}
	if !found {
		create := VolumeCreateRequest{Name: restoreName, CreateKey: createKey, SizeGB: backup.SizeGB,
			AvailabilityDomain: f.config.AvailabilityDomain, SourceBackupID: backup.ID}
		tags := volumeTags(f.config, create)
		tags[tagResource] = resourceMemberRestore
		tags[tagRestoreMember], tags[tagRestoreBackup] = request.Member, backup.ID
		retry := retryToken(strings.Join([]string{f.config.Owner, string(f.config.Region), createKey}, ":"))
		_, createErr := f.provider.CreateVolume(ctx, create, tags, retry)
		if volume, found, err = v.findRestoredVolume(ctx, createKey); err != nil || !found {
			return RestoredVolume{}, errors.Join(ErrOutcomeUnknown, createErr, err,
				fmt.Errorf("restored volume %s was not observed after its create", restoreName))
		}
	}
	if volume, err = v.awaitRestored(ctx, volume.ID); err != nil {
		return RestoredVolume{}, err
	}
	attachment, err := v.attach(ctx, restoreName, volume.ID, request.ScratchInstanceID, RestoreVolumeDevice)
	if err != nil {
		return RestoredVolume{}, err
	}
	// Read back what restore-check will mount: the scratch instance holds
	// exactly this restored volume at RestoreVolumeDevice.
	attachment, err = v.VerifyRestoredAttachment(ctx, request.ScratchInstanceID, volume.ID)
	if err != nil {
		return RestoredVolume{}, err
	}
	return RestoredVolume{BackupID: backup.ID, Attachment: attachment}, nil
}

// VerifyRestoredAttachment reads the exact restored volume and its exclusive
// attachment before restore-check mounts it. It performs no OCI mutations.
func (v *MemberVolumes) VerifyRestoredAttachment(ctx context.Context, scratchInstanceID, restoredVolumeID string) (Attachment, error) {
	if scratchInstanceID == "" || restoredVolumeID == "" {
		return Attachment{}, errors.New("restore verification requires scratch instance and restored volume IDs")
	}
	if err := v.requireScratchInstance(ctx, scratchInstanceID); err != nil {
		return Attachment{}, err
	}
	f := v.fleet
	volume, identity, err := f.reobserveVolumeResource(ctx, restoredVolumeID, resourceMemberRestore)
	if err != nil {
		return Attachment{}, err
	}
	if volume.LifecycleState != "AVAILABLE" || !f.memberName(volume.FreeformTags[tagRestoreMember], false) || volume.FreeformTags[tagRestoreBackup] == "" || identity.CreateKey != entityid.Derive("restore-volume", f.config.Owner, volume.FreeformTags[tagRestoreMember], volume.FreeformTags[tagRestoreBackup]) {
		return Attachment{}, fmt.Errorf("%w: volume %s is not an available restore copy", ErrForeignResource, restoredVolumeID)
	}
	if err := v.requireOnlyAttachment(ctx, scratchInstanceID, restoredVolumeID, true); err != nil {
		return Attachment{}, err
	}
	records, err := f.findVolumeAttachments(ctx, restoredVolumeID)
	if err != nil {
		return Attachment{}, err
	}
	live := liveAttachments(records)
	if len(live) != 1 || live[0].InstanceID != scratchInstanceID {
		return Attachment{}, fmt.Errorf("%w: restored volume %s has no exclusive scratch attachment", ErrAttachmentRecoveryHold, restoredVolumeID)
	}
	return f.reobserveAttachment(ctx, live[0].ID, restoredVolumeID, scratchInstanceID, RestoreVolumeDevice)
}

func (v *MemberVolumes) requireScratchInstance(ctx context.Context, instanceID string) error {
	f := v.fleet
	instance, err := f.provider.GetInstance(ctx, instanceID)
	if err != nil {
		return err
	}
	if instance.ID != instanceID || instance.CompartmentID != f.config.CompartmentID || instance.AvailabilityDomain != f.config.AvailabilityDomain {
		return fmt.Errorf("%w: scratch instance %s is outside the cell's compartment and availability domain", ErrForeignResource, instanceID)
	}
	if f.memberName(instance.DisplayName, false) {
		return fmt.Errorf("instance %s is member %s; a restore drill needs a scratch instance", instanceID, instance.DisplayName)
	}
	if instance.LifecycleState != "RUNNING" || instance.ConsistentVolumeNamingEnabled == nil || !*instance.ConsistentVolumeNamingEnabled {
		return fmt.Errorf("scratch instance %s must be RUNNING with consistent volume naming", instanceID)
	}
	return nil
}

func (v *MemberVolumes) selectBackup(ctx context.Context, backups volumeBackupReader, name, backupID, source string) (CloudVolumeBackup, error) {
	current, _, found, err := v.fleet.findVolumeByCreateKey(ctx, memberVolumeCreateKey(name))
	if err != nil {
		return CloudVolumeBackup{}, err
	}
	switch {
	case found && source != "" && current.ID != source:
		return CloudVolumeBackup{}, fmt.Errorf("%w: data volume %s is %s, not the recorded %s", ErrForeignResource, name, current.ID, source)
	case found:
		source = current.ID
	case source == "":
		return CloudVolumeBackup{}, fmt.Errorf("data volume %s is gone and no recorded volume ID names its backups", name)
	}
	if backupID != "" {
		backup, err := backups.GetVolumeBackup(ctx, backupID)
		if err != nil {
			return CloudVolumeBackup{}, err
		}
		if backup.ID != backupID || backup.LifecycleState != "AVAILABLE" || backup.SizeGB < minRetainedVolumeSizeGB {
			return CloudVolumeBackup{}, fmt.Errorf("backup %s is %s at %d GB; it must be AVAILABLE", backupID, backup.LifecycleState, backup.SizeGB)
		}
		if backup.VolumeID != source {
			return CloudVolumeBackup{}, fmt.Errorf("%w: backup %s is of volume %s, not %s of %s", ErrForeignResource, backupID, backup.VolumeID, source, name)
		}
		return backup, nil
	}
	listed, err := backups.ListVolumeBackups(ctx, source)
	if err != nil {
		return CloudVolumeBackup{}, err
	}
	var newest CloudVolumeBackup
	for _, backup := range listed {
		if backup.VolumeID == source && backup.LifecycleState == "AVAILABLE" && backup.SizeGB >= minRetainedVolumeSizeGB &&
			backup.CreatedAt.After(newest.CreatedAt) {
			newest = backup
		}
	}
	if newest.ID == "" {
		return CloudVolumeBackup{}, fmt.Errorf("data volume %s (%s) has no AVAILABLE backup", name, source)
	}
	return newest, nil
}

func (v *MemberVolumes) findRestoredVolume(ctx context.Context, createKey string) (CloudVolume, bool, error) {
	f := v.fleet
	volumes, err := f.provider.ListVolumes(ctx, f.config.CompartmentID, f.config.AvailabilityDomain)
	if err != nil {
		return CloudVolume{}, false, err
	}
	var found []CloudVolume
	for _, volume := range volumes {
		if volume.FreeformTags[tagCreateKey] == createKey && volume.LifecycleState != "TERMINATED" {
			found = append(found, volume)
		}
	}
	switch {
	case len(found) > 1:
		return CloudVolume{}, false, ErrDuplicateCreateKey
	case len(found) == 0:
		return CloudVolume{}, false, nil
	}
	volume, identity, err := f.reobserveVolumeResource(ctx, found[0].ID, resourceMemberRestore)
	if err != nil {
		return CloudVolume{}, false, err
	}
	if identity.CreateKey != createKey {
		return CloudVolume{}, false, ErrForeignResource
	}
	return volume, true, nil
}

// awaitRestored waits, bounded by restoreSettle, until the restored volume is
// AVAILABLE.
func (v *MemberVolumes) awaitRestored(ctx context.Context, volumeID string) (CloudVolume, error) {
	settleCtx, cancel := context.WithTimeout(ctx, v.restoreSettle)
	defer cancel()
	for {
		volume, _, err := v.fleet.reobserveVolumeResource(settleCtx, volumeID, resourceMemberRestore)
		if err != nil {
			return CloudVolume{}, err
		}
		switch volume.LifecycleState {
		case "AVAILABLE":
			return volume, nil
		case "PROVISIONING", "RESTORING":
		default:
			return CloudVolume{}, fmt.Errorf("restored volume %s is %s", volumeID, volume.LifecycleState)
		}
		select {
		case <-settleCtx.Done():
			return CloudVolume{}, fmt.Errorf("restored volume %s is still %s: %w", volumeID, volume.LifecycleState, settleCtx.Err())
		case <-time.After(attachmentSettlePoll):
		}
	}
}

// requireOnlyAttachment fails when the scratch instance has a live volume
// attachment other than the restored volume, or, with attached, unless that
// volume is attached at RestoreVolumeDevice.
func (v *MemberVolumes) requireOnlyAttachment(ctx context.Context, instanceID, volumeID string, attached bool) error {
	f := v.fleet
	listed, err := f.provider.ListVolumeAttachments(ctx, f.config.CompartmentID, instanceID)
	if err != nil {
		return err
	}
	found := false
	count := 0
	for _, attachment := range liveAttachments(listed) {
		if attachment.InstanceID != instanceID {
			continue
		}
		count++
		if attachment.VolumeID != volumeID {
			return fmt.Errorf("scratch instance %s also has volume %s attached; a restore drill needs it to hold only the restored volume",
				instanceID, attachment.VolumeID)
		}
		found = attachment.LifecycleState == "ATTACHED" && attachment.Device == RestoreVolumeDevice
	}
	if count > 1 {
		return fmt.Errorf("%w: scratch instance %s has multiple live attachments", ErrAttachmentRecoveryHold, instanceID)
	}
	if attached && !found {
		return fmt.Errorf("restored volume %s is not attached at %s on scratch instance %s", volumeID, RestoreVolumeDevice, instanceID)
	}
	return nil
}

type fakeDispatcher struct{}

func (fakeDispatcher) Do(*http.Request) (*http.Response, error) {
	return &http.Response{StatusCode: http.StatusOK, Body: http.NoBody}, nil
}

var Metrics = ociclient.Metrics

// APIView returns per-operation OCI API usage since process start and the
// latest fleet inventory by lifecycle state.
func APIView() observability.OCIView {
	return observability.OCIView{Operations: ociclient.APIOperations(), Fleet: FleetInventory()}
}

func Instrument(next common.HTTPRequestDispatcher, service string) common.HTTPRequestDispatcher {
	if next == nil {
		next = http.DefaultClient
	}
	return &instrumentedDispatcher{next: next, service: service, now: time.Now}
}

func (dispatcher *instrumentedDispatcher) Do(request *http.Request) (*http.Response, error) {
	started := dispatcher.now()
	response, err := dispatcher.next.Do(request)
	elapsed := dispatcher.now().Sub(started)
	status := 0
	if response != nil {
		status = response.StatusCode
	}
	apiStats.record(dispatcher.service, operationTemplate(request), status, err != nil, elapsed)
	return response, err
}

func (stats *operationStats) record(service, operation string, status int, transportError bool, elapsed time.Duration) {
	stats.mu.Lock()
	key := apiOperationKey{service: service, operation: operation}
	view, known := stats.byKey[key]
	if !known {
		if stats.perService[service] >= maxOperationsPerService {
			key.operation = "other"
			view, known = stats.byKey[key]
		}
		if !known {
			view = &observability.OCIOperationView{Service: service, Operation: key.operation}
			stats.byKey[key] = view
			stats.perService[service]++
		}
	}
	seconds := elapsed.Seconds()
	view.Calls++
	view.TotalSeconds += seconds
	view.MaxSeconds = max(view.MaxSeconds, seconds)
	view.LastStatus = status
	failed := transportError || status >= 400
	if failed {
		view.Errors++
		view.LastErrorCode = status
	}
	if status == http.StatusTooManyRequests {
		view.Throttled++
	}
	operation = key.operation
	stats.mu.Unlock()

	code := strconv.Itoa(status)
	if transportError {
		code = "transport_error"
	}
	labels := []string{"service", service, "operation", operation}
	Metrics.GetOrCreateCounter(observability.Series(observability.MetricPrefix+"oci_requests_total",
		slices.Concat(labels, []string{"code", code})...)).Inc()
	Metrics.GetOrCreatePrometheusHistogram(observability.Series(observability.MetricPrefix+"oci_request_duration_seconds",
		labels...)).Update(seconds)
	if status == http.StatusTooManyRequests {
		Metrics.GetOrCreateCounter(observability.Series(observability.MetricPrefix+"oci_throttled_total", labels...)).Inc()
	}
}

// APIOperations returns per-operation OCI API usage since process start.
func APIOperations() []observability.OCIOperationView {
	apiStats.mu.Lock()
	defer apiStats.mu.Unlock()
	operations := make([]observability.OCIOperationView, 0, len(apiStats.byKey))
	for _, operation := range apiStats.byKey {
		operations = append(operations, *operation)
	}
	slices.SortFunc(operations, func(a, b observability.OCIOperationView) int {
		return cmp.Or(cmp.Compare(a.Service, b.Service), cmp.Compare(a.Operation, b.Operation))
	})
	return operations
}

// operationTemplate turns "GET /20160918/instances/ocid1.instance...?page=x"
// into "GET /instances/{id}". The API version segment is dropped, resource
// identifiers become {id}, and only a bounded action query is kept.
func operationTemplate(request *http.Request) string {
	if request == nil || request.URL == nil {
		return "unknown"
	}
	segments := strings.Split(strings.Trim(request.URL.Path, "/"), "/")
	if len(segments) > 0 && apiVersionSegment(segments[0]) {
		segments = segments[1:]
	}
	// Object Storage names have fixed positions; object names can contain slashes.
	if len(segments) > 1 && segments[0] == "n" {
		segments[1] = "{id}"
		if len(segments) > 3 {
			segments[3] = "{id}"
		}
		end := 5
		if len(segments) > 4 && segments[4] == "actions" {
			end = 6
		}
		if len(segments) > end {
			segments = append(segments[:end], "{id}")
		}
	}
	if len(segments) > 8 {
		segments = append(segments[:8], "...")
	}
	for index, segment := range segments {
		if identifierSegment(segment) {
			segments[index] = "{id}"
		}
	}
	template := request.Method + " /" + strings.Join(segments, "/")
	if action := request.URL.Query().Get("action"); action != "" {
		if !boundedAction(action) {
			action = "{action}"
		}
		template += "?action=" + action
	}
	return template
}

