type observeSDKReadback struct {
	config           RegionConfig
	instances        map[string]CloudInstance
	badBootID        string
	failInstanceID   string
	failure          error
	getInstanceCalls map[string]int
	mutations        int
}

func (readback *observeSDKReadback) Do(request *http.Request) (*http.Response, error) {
	if request.Method != http.MethodGet {
		readback.mutations++
		return nil, errors.New("unexpected OCI mutation")
	}
	var payload any
	var etag string
	path := request.URL.Path
	switch {
	case strings.HasPrefix(path, "/20160918/instances/"):
		id := strings.TrimPrefix(path, "/20160918/instances/")
		readback.getInstanceCalls[id]++
		if id == readback.failInstanceID {
			return nil, readback.failure
		}
		instance, found := readback.instances[id]
		if !found {
			return nil, fmt.Errorf("unknown test instance %s", id)
		}
		etag = instance.ETag
		payload = map[string]any{"id": instance.ID, "compartmentId": instance.CompartmentID,
			"availabilityDomain": instance.AvailabilityDomain, "faultDomain": instance.FaultDomain,
			"shape": instance.Shape, "shapeConfig": map[string]any{"ocpus": instance.Ocpus,
				"memoryInGBs": instance.MemoryInGBs}, "lifecycleState": instance.LifecycleState,
			"imageId": instance.ImageID, "metadata": instance.Metadata, "freeformTags": instance.FreeformTags}
	case strings.HasSuffix(path, "/bootVolumeAttachments"):
		id := request.URL.Query().Get("instanceId")
		if _, found := readback.instances[id]; !found {
			return nil, fmt.Errorf("unknown test boot attachment instance %s", id)
		}
		payload = []map[string]any{{"bootVolumeId": "ocid1.bootvolume." + id,
			"instanceId": id, "compartmentId": readback.config.CompartmentID,
			"availabilityDomain": readback.config.AvailabilityDomain, "lifecycleState": "ATTACHED"}}
	case strings.HasPrefix(path, "/20160918/bootVolumes/"):
		id := strings.TrimPrefix(path, "/20160918/bootVolumes/")
		instanceID := strings.TrimPrefix(id, "ocid1.bootvolume.")
		if _, found := readback.instances[instanceID]; !found {
			return nil, fmt.Errorf("unknown test boot volume %s", id)
		}
		size := int64(readback.config.BootVolumeGB)
		if instanceID == readback.badBootID {
			size++
		}
		payload = map[string]any{"id": id, "compartmentId": readback.config.CompartmentID,
			"imageId": readback.config.ImageID, "sizeInGBs": size,
			"vpusPerGB": readback.config.BootVolumeVPUsPerGB}
	case strings.HasSuffix(path, "/vnicAttachments"):
		id := request.URL.Query().Get("instanceId")
		if _, found := readback.instances[id]; !found {
			return nil, fmt.Errorf("unknown test VNIC attachment instance %s", id)
		}
		payload = []map[string]any{{"vnicId": "ocid1.vnic." + id, "instanceId": id,
			"subnetId": readback.config.SubnetID, "lifecycleState": "ATTACHED"}}
	case strings.HasPrefix(path, "/20160918/vnics/"):
		id := strings.TrimPrefix(path, "/20160918/vnics/")
		instanceID := strings.TrimPrefix(id, "ocid1.vnic.")
		instance, found := readback.instances[instanceID]
		if !found {
			return nil, fmt.Errorf("unknown test VNIC %s", id)
		}
		payload = map[string]any{"id": id, "subnetId": readback.config.SubnetID,
			"privateIp": instance.PrivateIP, "nsgIds": readback.config.NetworkSecurityGroupIDs,
			"skipSourceDestCheck": false, "lifecycleState": "AVAILABLE"}
	default:
		return nil, fmt.Errorf("unexpected OCI test request %s", request.URL)
	}
	wire, err := json.Marshal(payload)
	if err != nil {
		return nil, err
	}
	header := make(http.Header)
	header.Set("Content-Type", "application/json")
	if etag != "" {
		header.Set("etag", etag)
	}
	return &http.Response{StatusCode: http.StatusOK, Header: header,
		Body: io.NopCloser(bytes.NewReader(wire)), Request: request}, nil
}

func (provider *sdkProvider) GetInstance(ctx context.Context, id string) (CloudInstance, error) {
	response, err := provider.compute.GetInstance(ociclient.RequestContext(ctx), core.GetInstanceRequest{InstanceId: new(id)})
	if err != nil {
		return CloudInstance{}, fmt.Errorf("get OCI instance: %w", err)
	}
	instance := cloudInstance(response.Instance, stringValue(response.Etag))
	if instance.LifecycleState != "TERMINATED" && instance.LifecycleState != "TERMINATING" {
		if privateIP, ok := provider.verified.lookup(ctx, instance.ID, instance.ETag); ok &&
			instance.CompartmentID == provider.config.CompartmentID &&
			instance.AvailabilityDomain == provider.config.AvailabilityDomain {
			instance.PrivateIP = privateIP
			return instance, nil
		}
		privateIP, err := provider.verifyInstanceStorageAndNetwork(ctx, instance)
		if err != nil {
			provider.verified.forget(instance.ID)
			return CloudInstance{}, err
		}
		provider.verified.store(instance.ID, instance.ETag, privateIP)
		instance.PrivateIP = privateIP
	}
	return instance, nil
}

func (provider *sdkProvider) verifyInstanceStorageAndNetwork(ctx context.Context, instance CloudInstance) (string, error) {
	return verifyInstanceStorageAndNetwork(ctx, provider.config, instance, provider.compute, provider.storage, provider.network)
}

type instanceAttachmentReader interface {
	ListBootVolumeAttachments(context.Context, core.ListBootVolumeAttachmentsRequest) (core.ListBootVolumeAttachmentsResponse, error)
	ListVnicAttachments(context.Context, core.ListVnicAttachmentsRequest) (core.ListVnicAttachmentsResponse, error)
}

type bootVolumeReader interface {
	GetBootVolume(context.Context, core.GetBootVolumeRequest) (core.GetBootVolumeResponse, error)
}

type vnicReader interface {
	GetVnic(context.Context, core.GetVnicRequest) (core.GetVnicResponse, error)
}

func verifyInstanceStorageAndNetwork(ctx context.Context, config RegionConfig, instance CloudInstance,
	compute instanceAttachmentReader, storage bootVolumeReader, network vnicReader) (string, error) {
	if instance.CompartmentID != config.CompartmentID ||
		instance.AvailabilityDomain != config.AvailabilityDomain {
		return "", ErrForeignResource
	}
	boots, err := compute.ListBootVolumeAttachments(sdkObservationContext(ctx, compute), core.ListBootVolumeAttachmentsRequest{
		CompartmentId: new(instance.CompartmentID), AvailabilityDomain: new(instance.AvailabilityDomain),
		InstanceId: new(instance.ID),
	})
	if err != nil {
		return "", fmt.Errorf("list exact instance boot attachment: %w", err)
	}
	if len(boots.Items) == 0 && stringValue(boots.OpcNextPage) == "" {
		return "", fmt.Errorf("%w: boot volume attachment is not visible yet", ErrOutcomeUnknown)
	}
	if len(boots.Items) == 1 && stringValue(boots.OpcNextPage) == "" &&
		(boots.Items[0].LifecycleState == core.BootVolumeAttachmentLifecycleStateAttaching ||
			boots.Items[0].LifecycleState == core.BootVolumeAttachmentLifecycleStateDetaching) &&
		stringValue(boots.Items[0].InstanceId) == instance.ID {
		return "", fmt.Errorf("%w: boot volume attachment is transitioning", ErrOutcomeUnknown)
	}
	if len(boots.Items) != 1 || stringValue(boots.OpcNextPage) != "" ||
		boots.Items[0].LifecycleState != core.BootVolumeAttachmentLifecycleStateAttached ||
		stringValue(boots.Items[0].InstanceId) != instance.ID ||
		stringValue(boots.Items[0].BootVolumeId) == "" {
		return "", fmt.Errorf("%w: instance has no single attached boot volume", ErrForeignResource)
	}
	boot, err := storage.GetBootVolume(sdkObservationContext(ctx, storage), core.GetBootVolumeRequest{
		BootVolumeId: boots.Items[0].BootVolumeId,
	})
	if err != nil {
		return "", fmt.Errorf("get exact instance boot volume: %w", err)
	}
	if stringValue(boot.Id) != stringValue(boots.Items[0].BootVolumeId) ||
		stringValue(boot.CompartmentId) != config.CompartmentID ||
		instance.ImageID == "" || stringValue(boot.ImageId) != instance.ImageID ||
		int64Value(boot.SizeInGBs) != int64(config.BootVolumeGB) ||
		int64Value(boot.VpusPerGB) != int64(config.BootVolumeVPUsPerGB) {
		return "", errors.Join(ErrForeignResource,
			fmt.Errorf("%w: instance boot image, size, or tier differs from the instance image and fleet pins", ErrImageNotQualified))
	}
	attachments, err := compute.ListVnicAttachments(sdkObservationContext(ctx, compute), core.ListVnicAttachmentsRequest{
		CompartmentId: new(instance.CompartmentID), InstanceId: new(instance.ID),
	})
	if err != nil {
		return "", fmt.Errorf("list exact instance VNIC: %w", err)
	}
	if len(attachments.Items) == 0 && stringValue(attachments.OpcNextPage) == "" {
		return "", fmt.Errorf("%w: primary VNIC attachment is not visible yet", ErrOutcomeUnknown)
	}
	if len(attachments.Items) == 1 && stringValue(attachments.OpcNextPage) == "" &&
		(attachments.Items[0].LifecycleState == core.VnicAttachmentLifecycleStateAttaching ||
			attachments.Items[0].LifecycleState == core.VnicAttachmentLifecycleStateDetaching) &&
		stringValue(attachments.Items[0].InstanceId) == instance.ID {
		return "", fmt.Errorf("%w: primary VNIC attachment is transitioning", ErrOutcomeUnknown)
	}
	if len(attachments.Items) != 1 || stringValue(attachments.OpcNextPage) != "" ||
		attachments.Items[0].LifecycleState != core.VnicAttachmentLifecycleStateAttached ||
		stringValue(attachments.Items[0].InstanceId) != instance.ID ||
		stringValue(attachments.Items[0].VnicId) == "" {
		return "", fmt.Errorf("%w: instance has no single attached primary VNIC", ErrForeignResource)
	}
	vnic, err := network.GetVnic(sdkObservationContext(ctx, network), core.GetVnicRequest{VnicId: attachments.Items[0].VnicId})
	if err != nil {
		return "", fmt.Errorf("get exact instance VNIC: %w", err)
	}
	gotNSGs := slices.Clone(vnic.NsgIds)
	wantNSGs := slices.Clone(config.NetworkSecurityGroupIDs)
	slices.Sort(gotNSGs)
	slices.Sort(wantNSGs)
	if stringValue(vnic.Id) != stringValue(attachments.Items[0].VnicId) ||
		stringValue(vnic.SubnetId) != config.SubnetID ||
		!validManagedPrivateIP(stringValue(vnic.PrivateIp)) || stringValue(vnic.PublicIp) != "" ||
		vnic.SkipSourceDestCheck != nil && *vnic.SkipSourceDestCheck ||
		vnic.LifecycleState != core.VnicLifecycleStateAvailable ||
		!slices.Equal(gotNSGs, wantNSGs) {
		return "", fmt.Errorf("%w: instance VNIC differs from the private subnet and NSG pins", ErrForeignResource)
	}
	return stringValue(vnic.PrivateIp), nil
}

type observeOnlyKey struct{}

// observeOnly marks a context as the read-only placement Observe sweep. Only
// that sweep may reuse a cached verification; every path that precedes a
// mutation verifies afresh.
func observeOnly(ctx context.Context) context.Context {
	return context.WithValue(ctx, observeOnlyKey{}, true)
}

// WithCachedVerification opts one Observe call into reusing a cached
// storage and network verification. Only placement's periodic read sweep
// passes it; admission paths (host enrollment, registration verification)
// call Observe with a plain context and always verify afresh.
func WithCachedVerification(ctx context.Context) context.Context { return observeOnly(ctx) }

func isObserveOnly(ctx context.Context) bool {
	marked, _ := ctx.Value(observeOnlyKey{}).(bool)
	return marked
}

type cachedVerification struct {
	etag      string
	privateIP string
	at        time.Time
}

// verificationCache remembers a successful boot volume, VNIC, subnet and NSG
// verification per instance ETag. Each Observe tick otherwise issues four
// extra OCI reads per member host (ListBootVolumeAttachments, GetBootVolume,
// ListVnicAttachments, GetVnic). An instance ETag change, a verification
// failure, or the TTL expiring forces a fresh verification.
//
// The cache trades detection latency of out-of-band VNIC or boot volume
// changes (up to one minute) for OCI read volume. Admission and mutation
// paths always verify afresh.
type verificationCache struct {
	now func() time.Time

	mu      sync.Mutex
	entries map[string]cachedVerification
}

func newVerificationCache() *verificationCache {
	return &verificationCache{now: time.Now, entries: map[string]cachedVerification{}}
}

func (c *verificationCache) lookup(ctx context.Context, id, etag string) (string, bool) {
	if c == nil || etag == "" || !isObserveOnly(ctx) {
		return "", false
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	entry, ok := c.entries[id]
	if !ok || entry.etag != etag || c.now().Sub(entry.at) >= observeVerificationTTL {
		return "", false
	}
	return entry.privateIP, true
}

func (c *verificationCache) store(id, etag, privateIP string) {
	if c == nil || etag == "" {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	now := c.now()
	for key, entry := range c.entries {
		if now.Sub(entry.at) >= observeVerificationTTL {
			delete(c.entries, key)
		}
	}
	if len(c.entries) >= maxFleetInstances {
		return
	}
	c.entries[id] = cachedVerification{etag: etag, privateIP: privateIP, at: now}
}

func (c *verificationCache) forget(id string) {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	delete(c.entries, id)
}

