func (p *fakeProvider) CreateVolume(_ context.Context, request VolumeCreateRequest, tags map[string]string, retry string) (CloudVolume, error) {
	p.volumeCreateCalls++
	if id, exists := p.volumeRetryTokens[retry]; exists {
		return p.volumes[id], p.volumeRetryReplayError
	}
	p.volumeCreates++
	p.volumeCreateRequests = append(p.volumeCreateRequests, request)
	id := fmt.Sprintf("ocid1.volume.created-%d", p.volumeCreates)
	volume := CloudVolume{
		ID: id, CompartmentID: p.config.CompartmentID, AvailabilityDomain: request.AvailabilityDomain,
		SizeGB: request.SizeGB, VPUsPerGB: int64(p.config.DataVolumeVPUsPerGB),
		LifecycleState: "PROVISIONING", ETag: "volume-etag", FreeformTags: cloneStringMap(tags),
	}
	p.volumes[id] = volume
	p.volumeRetryTokens[retry] = id
	createErr := p.volumeCreateErrorAfterCreate
	p.volumeCreateErrorAfterCreate = nil
	if p.afterVolumeCreate != nil {
		p.afterVolumeCreate()
	}
	volume.FreeformTags = cloneStringMap(volume.FreeformTags)
	return volume, createErr
}

func (f *fleet) DiscoverTerminalTargets(ctx context.Context, intent authority.TerminalIntent) ([]authority.TerminalTarget, error) {
	if err := f.validateTerminalScope(intent); err != nil {
		return nil, err
	}
	instances, err := f.provider.ListInstances(ctx, f.config.CompartmentID)
	if err != nil {
		return nil, fmt.Errorf("list terminal instance inventory: %w", err)
	}
	volumes, err := f.provider.ListVolumes(ctx, f.config.CompartmentID, f.config.AvailabilityDomain)
	if err != nil {
		return nil, fmt.Errorf("list terminal data inventory: %w", err)
	}
	if len(instances) > maxProviderItems || len(volumes) > maxProviderItems {
		return nil, errors.New("terminal OCI inventory exceeds safety bound")
	}
	operations, err := f.journal.ListOperations(ctx)
	if err != nil {
		return nil, err
	}
	targets := make([]authority.TerminalTarget, len(intent.Targets))
	allowedHosts := make(map[string]bool, len(intent.Targets))
	allowedData := make(map[string]bool, len(intent.Targets))
	for i, target := range intent.Targets {
		if !terminalDataKeyMatches(intent, target) {
			return nil, fmt.Errorf("%w: seat %s has a data create key outside its workload", ErrForeignResource, target.SeatID)
		}
		allowedHosts[target.HostCreateKey] = true
		allowedData[target.DataCreateKey] = true
		resolved := target
		resolved.InstanceID, resolved.BootVolumeID, resolved.DataVolumeID = "", "", ""
		launch, launchResult, launchFound, err := f.terminalCreateResult(ctx, actionLaunch, target.HostCreateKey)
		if err != nil {
			return nil, err
		}
		if launchFound {
			descriptor, err := launchIntentDescriptor(launch)
			if err != nil || descriptor.DatabaseID != intent.DatabaseID || descriptor.PartitionID != intent.PartitionID ||
				descriptor.SeatID != target.SeatID || descriptor.IntentGeneration != intent.PlacementGeneration ||
				descriptor.IntentPayloadDigest != intent.PlacementPayloadDigest {
				return nil, fmt.Errorf("%w: host launch differs from signed terminal placement", ErrHostBootBindingMismatch)
			}
			resolved.InstanceID = launchResult.ResourceID
			binding, found, err := f.journal.GetBootBinding(ctx, resolved.InstanceID)
			if err != nil {
				return nil, err
			}
			if !found || !f.terminalBootBindingMatches(binding, resolved.InstanceID, launch) {
				return nil, fmt.Errorf("%w: host %s lacks its active-instance boot binding", ErrForeignResource, resolved.InstanceID)
			}
			resolved.BootVolumeID = binding.BootVolumeID
		}
		volumeIntent, volumeResult, volumeFound, err := f.terminalCreateResult(ctx, actionVolumeCreate, target.DataCreateKey)
		if err != nil {
			return nil, err
		}
		if volumeFound {
			if volumeIntent.AvailabilityDomain != f.config.AvailabilityDomain || volumeIntent.SizeGB < minRetainedVolumeSizeGB ||
				volumeIntent.SizeGB > f.config.MaxDataVolumeGB {
				return nil, fmt.Errorf("%w: terminal data create profile differs from fleet", ErrForeignResource)
			}
			resolved.DataVolumeID = volumeResult.ResourceID
		}
		if target.InstanceID != "" && target.InstanceID != resolved.InstanceID ||
			target.BootVolumeID != "" && target.BootVolumeID != resolved.BootVolumeID ||
			target.DataVolumeID != "" && target.DataVolumeID != resolved.DataVolumeID {
			return nil, fmt.Errorf("%w: seat %s differs from durable terminal inventory", ErrForeignResource, target.SeatID)
		}
		if err := checkTerminalListed(instances, target.HostCreateKey, resolved.InstanceID); err != nil {
			return nil, err
		}
		if err := checkTerminalListed(volumes, target.DataCreateKey, resolved.DataVolumeID); err != nil {
			return nil, err
		}
		targets[i] = resolved
	}
	for _, record := range operations {
		op := record.Intent
		if op.Region != f.config.Region || op.Generation != f.config.Generation || op.Owner != f.config.Owner {
			continue
		}
		if op.Action == actionLaunch {
			descriptor, err := launchIntentDescriptor(op)
			if err != nil {
				return nil, err
			}
			if descriptor.DatabaseID == intent.DatabaseID && descriptor.PartitionID == intent.PartitionID && !allowedHosts[op.CreateKey] {
				return nil, fmt.Errorf("%w: workload has an unlisted host create attempt", ErrForeignResource)
			}
		}
		if (allowedHosts[op.CreateKey] || allowedData[op.CreateKey] || terminalOperationTouches(op, targets)) &&
			op.Action != actionTerminalTerminate && op.Action != actionTerminalBootDelete && op.Action != actionTerminalDataDelete &&
			(record.Result.RecordedAt.IsZero() || record.Result.Unknown) && !f.resizeSettled(ctx, op, volumes) &&
			!f.detachSettled(ctx, op) {
			return nil, fmt.Errorf("%w: prior OCI operation %s remains unsettled", ErrOutcomeUnknown, op.Action)
		}
	}
	return targets, nil
}

// resizeSettledByObservation reports a grow-only resize whose outcome no
// longer matters: the listed volume is already at or past its target (the

func (f *fleet) VerifyTerminalInventorySettled(ctx context.Context, intent authority.TerminalIntent) error {
	_, err := f.inspectTerminalInventory(ctx, intent)
	return err
}

func (f *fleet) inspectTerminalInventory(ctx context.Context, intent authority.TerminalIntent) ([]string, error) {
	var terminated []string
	resolved, err := f.DiscoverTerminalTargets(ctx, intent)
	if err != nil {
		return terminated, err
	}
	for i, target := range resolved {
		if target != intent.Targets[i] {
			return terminated, fmt.Errorf("%w: seat %s has an omitted or changed resource ID", ErrForeignResource, target.SeatID)
		}
		if target.InstanceID != "" {
			cloud, err := f.provider.GetInstance(ctx, target.InstanceID)
			if err != nil && !isNotFound(err) {
				return terminated, err
			}
			if err == nil {
				if cloud.ID != target.InstanceID || cloud.CompartmentID != f.config.CompartmentID {
					return terminated, ErrForeignResource
				}
				if cloud.LifecycleState != "TERMINATED" {
					if _, _, err := f.reobserveLaunch(ctx, target.InstanceID, false); err != nil {
						return terminated, fmt.Errorf("%w: terminal instance has no positive ownership: %v", ErrForeignResource, err)
					}
				}
			}
			image, err := f.terminalBootImage(ctx, target)
			if err != nil {
				return terminated, err
			}
			boot, err := f.provider.GetBootVolume(ctx, target.BootVolumeID)
			if err != nil && !isNotFound(err) {
				return terminated, err
			}
			if err == nil && !f.terminalBootMatches(boot, target.BootVolumeID, image) {
				return terminated, fmt.Errorf("%w: terminal boot volume differs from fleet pins", ErrForeignResource)
			}
		}
		if target.DataVolumeID != "" {
			volume, _, err := f.reobserveVolume(ctx, target.DataVolumeID)
			if err != nil && !isNotFound(err) {
				return terminated, err
			}
			if err == nil && volume.LifecycleState == "TERMINATED" {
				terminated = append(terminated, volume.ID)
			}
		}
	}
	return terminated, nil
}

func (f *fleet) ReconcileTerminal(ctx context.Context, intent authority.TerminalIntent, markerSeq uint64) (TerminalStatus, error) {
	status := TerminalStatus{Phase: "pending"}
	if err := f.requireTerminalMarker(ctx, intent, markerSeq); err != nil {
		return status, err
	}
	terminated, err := f.inspectTerminalInventory(ctx, intent)
	for _, id := range terminated {
		if writeErr := f.journal.RecordVolumeTermination(ctx, f.config, id); writeErr != nil {
			return status, errors.Join(err, writeErr)
		}
	}
	if err != nil {
		return status, err
	}
	for _, target := range intent.Targets {
		if target.InstanceID != "" {
			settled, err := f.reconcileTerminalInstance(ctx, intent, markerSeq, target)
			if err != nil {
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.InstanceID)
				continue
			}
			settled, err = f.reconcileTerminalBoot(ctx, intent, markerSeq, target)
			if err != nil {
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.BootVolumeID)
			}
		}
		if target.DataVolumeID != "" {
			settled, err := f.reconcileTerminalData(ctx, intent, markerSeq, target)
			if err != nil {
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.DataVolumeID)
			}
		}
	}
	if len(status.Pending) == 0 {
		status.Phase = "complete"
	}
	return status, nil
}

func (f *fleet) validateTerminalScope(intent authority.TerminalIntent) error {
	if err := intent.Validate(); err != nil {
		return err
	}
	if intent.Region != string(f.config.Region) || intent.Cell != strings.ToLower(string(f.config.Region)) ||
		intent.Owner != f.config.Owner || intent.CompartmentID != f.config.CompartmentID ||
		intent.FleetGeneration != f.config.Generation {
		return fmt.Errorf("%w: terminal intent differs from pinned OCI fleet", ErrForeignResource)
	}
	permanentSeat := entityid.Derive("placement-seat", string(f.config.Region), "1")
	elasticSeat := entityid.Derive("placement-seat", string(f.config.Region), "2")
	if len(intent.Targets) != 2 || intent.Targets[0].SeatID != permanentSeat || intent.Targets[1].SeatID != elasticSeat {
		return fmt.Errorf("%w: terminal intent must pin the two ordered workload seats", ErrForeignResource)
	}
	return nil
}

func (f *fleet) terminalCreateResult(ctx context.Context, action, key string) (OperationIntent, OperationResult, bool, error) {
	op, exists, err := f.journal.GetOperation(ctx, OperationScope{Action: action, Key: key, Region: f.config.Region,
		Generation: f.config.Generation, Owner: f.config.Owner})
	if err != nil || !exists {
		return op, OperationResult{}, false, err
	}
	result, found, err := f.journal.GetResult(ctx, op)
	if err != nil {
		return op, result, false, err
	}
	if !found || result.Unknown || result.ResourceID == "" {
		return op, result, false, fmt.Errorf("%w: %s %s has no confirmed create result", ErrOutcomeUnknown, action, key)
	}
	return op, result, true, nil
}

func terminalDataKeyMatches(intent authority.TerminalIntent, target authority.TerminalTarget) bool {
	return target.DataCreateKey == terminalDigestToken("tv", intent.DatabaseID, intent.PartitionID, intent.Region, target.SeatID)
}

func terminalOperationTouches(op OperationIntent, targets []authority.TerminalTarget) bool {
	for _, target := range targets {
		if op.ResourceID != "" && (op.ResourceID == target.InstanceID || op.ResourceID == target.DataVolumeID) ||
			op.VolumeID != "" && op.VolumeID == target.DataVolumeID {
			return true
		}
	}
	return false
}

func checkTerminalListed[T CloudInstance | CloudVolume](items []T, key, expected string) error {
	count := 0
	for _, item := range items {
		var id string
		var tags map[string]string
		switch value := any(item).(type) {
		case CloudInstance:
			id, tags = value.ID, value.FreeformTags
		case CloudVolume:
			id, tags = value.ID, value.FreeformTags
		}
		if tags[tagCreateKey] != key {
			continue
		}
		count++
		if id != expected {
			return fmt.Errorf("%w: create key %s resolves to an unpinned resource", ErrForeignResource, key)
		}
	}
	if count > 1 {
		return ErrDuplicateCreateKey
	}
	return nil
}

// terminalBootBindingMatches binds a boot binding to the host's launch,
// image included. Teardown trusts these journaled records, not the current
// allow-list, so a revoked image never strands its hosts' cleanup.
func (f *fleet) terminalBootBindingMatches(binding BootBinding, instanceID string, launch OperationIntent) bool {
	return binding.InstanceID == instanceID && binding.Region == f.config.Region && binding.Generation == f.config.Generation &&
		binding.Owner == f.config.Owner && binding.CreateKey == launch.CreateKey &&
		binding.CompartmentID == f.config.CompartmentID && binding.AvailabilityDomain == f.config.AvailabilityDomain &&
		binding.ImageID == launch.ImageID && binding.SizeGB == int64(f.config.BootVolumeGB) &&
		binding.VPUsPerGB == int64(f.config.BootVolumeVPUsPerGB)
}

// terminalBootImage is the image of target's journaled boot binding.
func (f *fleet) terminalBootImage(ctx context.Context, target authority.TerminalTarget) (string, error) {
	binding, found, err := f.journal.GetBootBinding(ctx, target.InstanceID)
	if err != nil {
		return "", fmt.Errorf("read OCI host boot binding: %w", err)
	}
	if !found || binding.BootVolumeID != target.BootVolumeID || binding.ImageID == "" {
		return "", fmt.Errorf("%w: boot volume %s lacks its journaled boot binding", ErrForeignResource, target.BootVolumeID)
	}
	return binding.ImageID, nil
}

func (f *fleet) terminalBootMatches(boot CloudBootVolume, id, imageID string) bool {
	return boot.ID == id && boot.CompartmentID == f.config.CompartmentID &&
		boot.AvailabilityDomain == f.config.AvailabilityDomain && boot.ImageID == imageID &&
		boot.SizeGB == int64(f.config.BootVolumeGB) && boot.VPUsPerGB == int64(f.config.BootVolumeVPUsPerGB) &&
		boot.ETag != ""
}

func (f *fleet) requireTerminalMarker(ctx context.Context, intent authority.TerminalIntent, sequence uint64) error {
	if sequence == 0 {
		return errors.New("terminal reconciliation requires an accepted marker sequence")
	}
	if err := f.validateTerminalScope(intent); err != nil {
		return err
	}
	reader, ok := f.fencer.(authority.TerminalIntentReader)
	if !ok {
		return errors.New("OCI authority cannot verify the terminal marker")
	}
	entry, err := reader.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID)
	if err != nil {
		return err
	}
	wire, err := json.Marshal(intent, json.Deterministic(true))
	if err != nil || entry.Kind != authority.MutationTerminalIntent || entry.Sequence != sequence ||
		entry.SubjectKey != intent.DatabaseID+"."+intent.PartitionID ||
		entry.OperationID != intent.OperationID || !bytes.Equal(entry.Payload, wire) {
		return errors.New("current terminal marker differs from accepted exact intent")
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return err
	}
	return f.guard(ctx, epoch)
}

func (f *fleet) terminalMutation(ctx context.Context, intent authority.TerminalIntent, markerSeq uint64,
	action, resourceID, createKey, etag string, mutate func() error, observe func() (bool, error),
) (bool, error) {
	key := digest(intent.OperationID, action, resourceID)
	op := f.intent(action, key, resourceID, createKey, etag, "", "")
	prior, found, err := f.journal.GetOperation(ctx, OperationScope{Action: action, Key: key, Region: f.config.Region,
		Generation: f.config.Generation, Owner: f.config.Owner})
	if err != nil {
		return false, err
	}
	if found {
		if prior.ResourceID != resourceID || prior.CreateKey != createKey || prior.ExpectedETag != etag {
			return false, ErrStaleETag
		}
		op = prior
		result, hasResult, err := f.journal.GetResult(ctx, op)
		if err != nil {
			return false, err
		}
		if hasResult && !result.Unknown {
			return observe()
		}
		// A prior request may have succeeded despite loss of its response. Only
		// readback may settle it; issuing a second destructive call is unsafe.
		settled, err := observe()
		if err != nil || !settled {
			return false, errors.Join(ErrOutcomeUnknown, err)
		}
		return true, f.terminalRecordResult(ctx, intent, markerSeq, op)
	}
	if err := f.requireTerminalMarker(ctx, intent, markerSeq); err != nil {
		return false, err
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return false, err
	}
	if err := f.recordIntent(ctx, epoch, op); err != nil {
		return false, err
	}
	if err := f.requireTerminalMarker(ctx, intent, markerSeq); err != nil {
		return false, err
	}
	callErr := mutate()
	settled, readErr := observe()
	if readErr != nil {
		return false, errors.Join(ErrOutcomeUnknown, callErr, readErr)
	}
	if !settled {
		if callErr != nil {
			return false, errors.Join(ErrOutcomeUnknown, callErr)
		}
		return false, nil
	}
	return true, f.terminalRecordResult(ctx, intent, markerSeq, op)
}

func (f *fleet) terminalRecordResult(ctx context.Context, intent authority.TerminalIntent, seq uint64, op OperationIntent) error {
	if err := f.requireTerminalMarker(ctx, intent, seq); err != nil {
		return err
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return err
	}
	return f.recordResult(ctx, epoch, OperationResult{Intent: op, ResourceID: op.ResourceID, ETag: op.ExpectedETag})
}

func (f *fleet) InspectTerminalStatus(ctx context.Context, intent authority.TerminalIntent) (TerminalStatus, error) {
	status := TerminalStatus{Phase: TerminalPhasePending}
	if err := f.VerifyTerminalInventorySettled(ctx, intent); err != nil {
		status.Phase = TerminalPhaseHeld
		return status, err
	}
	for _, target := range intent.Targets {
		if target.InstanceID != "" {
			settled, err := f.terminalInstanceSettled(ctx, target.InstanceID)
			if err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.InstanceID)
			} else if err := f.requireTerminalResultSettled(ctx, intent, actionTerminalTerminate, target.InstanceID); err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
			settled, err = f.terminalBootSettled(ctx, target)
			if err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.BootVolumeID)
			} else if err := f.requireTerminalResultSettled(ctx, intent, actionTerminalBootDelete, target.BootVolumeID); err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
		}
		if target.DataVolumeID != "" {
			settled, _, err := f.terminalDataSettled(ctx, target.DataVolumeID)
			if err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
			if !settled {
				status.Pending = append(status.Pending, target.DataVolumeID)
			} else if err := f.requireTerminalResultSettled(ctx, intent, actionTerminalDataDelete, target.DataVolumeID); err != nil {
				status.Phase = TerminalPhaseHeld
				return status, err
			}
		}
	}
	if len(status.Pending) == 0 {
		status.Phase = TerminalPhaseComplete
	}
	return status, nil
}

func (f *fleet) reconcileTerminalInstance(ctx context.Context, intent authority.TerminalIntent, seq uint64,
	target authority.TerminalTarget,
) (bool, error) {
	settled, err := f.terminalInstanceSettled(ctx, target.InstanceID)
	if err != nil || settled {
		if err != nil {
			return false, err
		}
		return true, f.settleTerminalRecorded(ctx, intent, seq, actionTerminalTerminate, target.InstanceID)
	}
	cloud, _, err := f.ownedLaunch(ctx, target.InstanceID, false)
	if err != nil {
		return false, err
	}
	if cloud.LifecycleState == "TERMINATING" || cloud.ETag == "" {
		return false, nil
	}
	return f.terminalMutation(ctx, intent, seq, actionTerminalTerminate, target.InstanceID,
		target.HostCreateKey, cloud.ETag,
		func() error { return f.provider.TerminateTerminalInstance(ctx, target.InstanceID, cloud.ETag) },
		func() (bool, error) { return f.terminalInstanceSettled(ctx, target.InstanceID) })
}

func (f *fleet) reconcileTerminalBoot(ctx context.Context, intent authority.TerminalIntent, seq uint64,
	target authority.TerminalTarget,
) (bool, error) {
	settled, err := f.terminalBootSettled(ctx, target)
	if err != nil || settled {
		if err != nil {
			return false, err
		}
		return true, f.settleTerminalRecorded(ctx, intent, seq, actionTerminalBootDelete, target.BootVolumeID)
	}
	attachments, err := f.provider.ListBootVolumeAttachments(ctx, target.BootVolumeID)
	if err != nil {
		return false, err
	}
	if activeBootAttachments(attachments, target.BootVolumeID) {
		return false, nil
	}
	image, err := f.terminalBootImage(ctx, target)
	if err != nil {
		return false, err
	}
	boot, err := f.provider.GetBootVolume(ctx, target.BootVolumeID)
	if err != nil {
		return false, err
	}
	if !f.terminalBootMatches(boot, target.BootVolumeID, image) {
		return false, ErrForeignResource
	}
	if boot.LifecycleState == "TERMINATING" {
		return false, nil
	}
	return f.terminalMutation(ctx, intent, seq, actionTerminalBootDelete, target.BootVolumeID,
		target.HostCreateKey, boot.ETag,
		func() error { return f.provider.DeleteBootVolume(ctx, target.BootVolumeID, boot.ETag) },
		func() (bool, error) { return f.terminalBootSettled(ctx, target) })
}

func (f *fleet) reconcileTerminalData(ctx context.Context, intent authority.TerminalIntent, seq uint64,
	target authority.TerminalTarget,
) (bool, error) {
	settled, err := f.reconcileTerminalDataReadback(ctx, target.DataVolumeID)
	if err != nil || settled {
		if err != nil {
			return false, err
		}
		return true, f.settleTerminalRecorded(ctx, intent, seq, actionTerminalDataDelete, target.DataVolumeID)
	}
	attachments, err := f.findVolumeAttachments(ctx, target.DataVolumeID)
	if err != nil {
		return false, err
	}
	if activeDataAttachments(attachments) {
		return false, nil
	}
	volume, err := f.ownedVolume(ctx, target.DataVolumeID)
	if err != nil {
		return false, err
	}
	if volume.LifecycleState == "TERMINATED" {
		if err := f.journal.RecordVolumeTermination(ctx, f.config, volume.ID); err != nil {
			return false, err
		}
		return true, f.settleTerminalRecorded(ctx, intent, seq, actionTerminalDataDelete, target.DataVolumeID)
	}
	if volume.ETag == "" {
		return false, ErrStaleETag
	}
	if volume.LifecycleState == "TERMINATING" {
		return false, nil
	}
	return f.terminalMutation(ctx, intent, seq, actionTerminalDataDelete, target.DataVolumeID,
		target.DataCreateKey, volume.ETag,
		func() error { return f.provider.DeleteVolume(ctx, target.DataVolumeID, volume.ETag) },
		func() (bool, error) { return f.reconcileTerminalDataReadback(ctx, target.DataVolumeID) })
}

func (f *fleet) terminalInstanceSettled(ctx context.Context, id string) (bool, error) {
	cloud, err := f.provider.GetInstance(ctx, id)
	if err != nil && !isNotFound(err) {
		return false, err
	}
	if err == nil {
		if cloud.ID != id || cloud.CompartmentID != f.config.CompartmentID {
			return false, ErrForeignResource
		}
		if cloud.LifecycleState != "TERMINATED" {
			return false, nil
		}
	}
	attachments, err := f.provider.ListVolumeAttachments(ctx, f.config.CompartmentID, id)
	if err != nil {
		return false, err
	}
	for _, attachment := range attachments {
		if attachment.InstanceID == id && attachment.LifecycleState != "DETACHED" && attachment.LifecycleState != "TERMINATED" {
			return false, nil
		}
	}
	return true, nil
}

func (f *fleet) terminalBootSettled(ctx context.Context, target authority.TerminalTarget) (bool, error) {
	id := target.BootVolumeID
	image, err := f.terminalBootImage(ctx, target)
	if err != nil {
		return false, err
	}
	boot, err := f.provider.GetBootVolume(ctx, id)
	if err != nil && !isNotFound(err) {
		return false, err
	}
	if err == nil {
		if !f.terminalBootMatches(boot, id, image) {
			return false, ErrForeignResource
		}
		if boot.LifecycleState != "TERMINATED" {
			return false, nil
		}
	}
	attachments, err := f.provider.ListBootVolumeAttachments(ctx, id)
	if err != nil {
		return false, err
	}
	return !activeBootAttachments(attachments, id), nil
}

// The second result identifies a positive TERMINATED read, never a 404.
func (f *fleet) terminalDataSettled(ctx context.Context, id string) (bool, bool, error) {
	volume, err := f.provider.GetVolume(ctx, id)
	if err != nil && !isNotFound(err) {
		return false, false, err
	}
	terminated := err == nil
	if terminated {
		if volume.ID != id || volume.CompartmentID != f.config.CompartmentID ||
			volume.AvailabilityDomain != f.config.AvailabilityDomain {
			return false, false, ErrForeignResource
		}
		if volume.LifecycleState != "TERMINATED" {
			return false, false, nil
		}
	}
	attachments, err := f.findVolumeAttachments(ctx, id)
	if err != nil {
		return false, terminated, err
	}
	return !activeDataAttachments(attachments), terminated, nil
}

func (f *fleet) reconcileTerminalDataReadback(ctx context.Context, id string) (bool, error) {
	settled, terminated, err := f.terminalDataSettled(ctx, id)
	if terminated {
		if writeErr := f.journal.RecordVolumeTermination(ctx, f.config, id); writeErr != nil {
			return false, errors.Join(err, writeErr)
		}
	}
	return settled, err
}

func activeBootAttachments(attachments []CloudBootAttachment, id string) bool {
	for _, attachment := range attachments {
		if attachment.BootVolumeID == id && attachment.LifecycleState != "DETACHED" && attachment.LifecycleState != "TERMINATED" {
			return true
		}
	}
	return false
}

func activeDataAttachments(attachments []CloudAttachment) bool {
	for _, attachment := range attachments {
		if attachment.LifecycleState != "DETACHED" && attachment.LifecycleState != "TERMINATED" {
			return true
		}
	}
	return false
}

func (f *fleet) settleTerminalRecorded(ctx context.Context, intent authority.TerminalIntent, seq uint64,
	action, id string,
) error {
	op, found, err := f.journal.GetOperation(ctx, OperationScope{Action: action,
		Key: digest(intent.OperationID, action, id), Region: f.config.Region,
		Generation: f.config.Generation, Owner: f.config.Owner})
	if err != nil || !found {
		return err
	}
	if op.ResourceID != id {
		return ErrForeignResource
	}
	result, hasResult, err := f.journal.GetResult(ctx, op)
	if err != nil {
		return err
	}
	if hasResult && !result.Unknown {
		return nil
	}
	return f.terminalRecordResult(ctx, intent, seq, op)
}

func (f *fleet) requireTerminalResultSettled(ctx context.Context, intent authority.TerminalIntent,
	action, id string,
) error {
	op, found, err := f.journal.GetOperation(ctx, OperationScope{Action: action,
		Key: digest(intent.OperationID, action, id), Region: f.config.Region,
		Generation: f.config.Generation, Owner: f.config.Owner})
	if err != nil || !found {
		return err
	}
	if op.ResourceID != id {
		return ErrForeignResource
	}
	result, hasResult, err := f.journal.GetResult(ctx, op)
	if err != nil {
		return err
	}
	if !hasResult || result.Unknown || result.ResourceID != id {
		return fmt.Errorf("%w: terminal %s %s has no durable readback result", ErrOutcomeUnknown, action, id)
	}
	return nil
}

func testJournalBucket(t *testing.T) jetstream.KeyValue {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Second)
	defer cancel()
	runtime, err := startAuthenticatedJournal(ctx, authenticatedJournalConfig(t, "oci-journal-test"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = runtime.Close() })
	journal, err := OpenJournal(ctx, runtime.JetStream(), 1)
	if err != nil {
		t.Fatal(err)
	}
	return journal.kv
}

func authenticatedJournalConfig(t *testing.T, instance string) natscell.Config {
	t.Helper()
	const cell = "lab"
	root := t.TempDir()
	write := func(name string, wire []byte) string {
		t.Helper()
		path := filepath.Join(root, name)
		if err := os.WriteFile(path, wire, 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	key := func(kind nkeys.PrefixByte) (nkeys.KeyPair, string) {
		t.Helper()
		pair, err := nkeys.CreatePair(kind)
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(pair.Wipe)
		public, err := pair.PublicKey()
		if err != nil {
			t.Fatal(err)
		}
		return pair, public
	}
	operator, operatorID := key(nkeys.PrefixByteOperator)
	system, systemID := key(nkeys.PrefixByteAccount)
	account, accountID := key(nkeys.PrefixByteAccount)
	claimFile := func(name string, claim jwt.Claims, signer nkeys.KeyPair) string {
		t.Helper()
		wire, err := claim.Encode(signer)
		if err != nil {
			t.Fatal(err)
		}
		return write(name, []byte(wire))
	}
	credentials := func(name string, user, signer nkeys.KeyPair, claim *jwt.UserClaims) string {
		t.Helper()
		wire, err := claim.Encode(signer)
		if err != nil {
			t.Fatal(err)
		}
		seed, err := user.Seed()
		if err != nil {
			t.Fatal(err)
		}
		defer clear(seed)
		creds, err := jwt.FormatUserConfig(wire, seed)
		if err != nil {
			t.Fatal(err)
		}
		defer clear(creds)
		return write(name, creds)
	}
	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	accountClaim := jwt.NewAccountClaims(accountID)
	accountClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 64 << 20, DiskStorage: 256 << 20, Streams: 10, Consumer: 10}
	systemUser, systemUserID := key(nkeys.PrefixByteUser)
	systemClaim := jwt.NewUserClaims(systemUserID)
	systemClaim.IssuerAccount = systemID
	systemClaim.Pub.Allow = jwt.StringList{"$SYS.REQ.ACCOUNT." + accountID + ".CLAIMS.UPDATE"}
	systemClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, systemUserID) + ".>"}
	controller, controllerID := key(nkeys.PrefixByteUser)
	controllerClaim := jwt.NewUserClaims(controllerID)
	controllerClaim.IssuerAccount = accountID
	controllerClaim.Pub.Allow = natscell.ControllerPublishes(cell)
	controllerClaim.Pub.Allow.Add("$JS.ACK.>")
	controllerClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, controllerID) + ".>"}
	controllerClaim.Sub.Allow.Add(natscell.ControllerSubscriptions(cell)...)
	controllerClaim.Sub.Allow.Add(protocol.Broker(cell, "ticket", ">"), protocol.Broker(cell, "fence", instance))
	controllerClaim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}

	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now()
	ca := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: "OCI journal test CA"},
		NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), IsCA: true, BasicConstraintsValid: true,
		KeyUsage: x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature}
	caDER, err := x509.CreateCertificate(rand.Reader, ca, ca, &caKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	peerKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	peer := &x509.Certificate{SerialNumber: big.NewInt(2), Subject: pkix.Name{CommonName: "OCI journal test peer"},
		NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), IPAddresses: []net.IP{net.ParseIP("127.0.0.1")},
		KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}}
	peerDER, err := x509.CreateCertificate(rand.Reader, peer, ca, &peerKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	keyDER, err := x509.MarshalECPrivateKey(peerKey)
	if err != nil {
		t.Fatal(err)
	}
	tlsFiles := natscell.TLSFiles{
		CAFile:   write("ca.pem", pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})),
		CertFile: write("peer.pem", pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: peerDER})),
		KeyFile:  write("peer-key.pem", pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER})),
	}
	ticketPublic, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	port := listener.Addr().(*net.TCPAddr).Port
	if err := listener.Close(); err != nil {
		t.Fatal(err)
	}
	cfg := natscell.Config{Cell: cell, Instance: instance, Replicas: 1, TLS: tlsFiles,
		CredentialsFile: credentials("controller.creds", controller, account, controllerClaim),
		Embedded: &natscell.Embedded{Host: "127.0.0.1", Port: port, StoreDir: filepath.Join(root, "jetstream"),
			TLS: tlsFiles, RouteTLS: tlsFiles, OperatorJWTFile: claimFile("operator.jwt", operatorClaim, operator),
			SystemJWTFile:         claimFile("system.jwt", jwt.NewAccountClaims(systemID), operator),
			CellJWTFile:           claimFile("cell.jwt", accountClaim, operator),
			SystemCredentialsFile: credentials("system.creds", systemUser, system, systemClaim),
			TicketPublicKeyFile:   write("ticket.pub", []byte(base64.StdEncoding.EncodeToString(ticketPublic))), BrokerIDs: []string{instance}}}
	if err := natscell.ValidateProductionCredentials(cfg); err != nil {
		t.Fatal(err)
	}
	return cfg
}

func startAuthenticatedJournal(ctx context.Context, cfg natscell.Config) (_ *authenticatedJournalRuntime, err error) {
	broker, err := natscell.Start(ctx, cfg)
	if err != nil {
		return nil, err
	}
	defer func() {
		if err != nil {
			_ = broker.Close()
		}
	}()
	claim := broker.InitialCellJWT()
	if err = broker.ApplyCellClaim(ctx, 1, claim); err != nil {
		return nil, err
	}
	if err = broker.Bridge().OpenUntil(1, claim, time.Now().Add(5*time.Minute)); err != nil {
		return nil, err
	}
	cfg.URL, cfg.Embedded = broker.URL(), nil
	client, err := natscell.Start(ctx, cfg)
	if err != nil {
		return nil, err
	}
	return &authenticatedJournalRuntime{Runtime: client, broker: broker}, nil
}

func (r *Runtime) Conn() *nats.Conn { return r.conn }

func (r *Runtime) JetStream() jetstream.JetStream { return r.js }

func (r *Runtime) Bridge() *Bridge { return r.bridge }

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func OpenJournal(ctx context.Context, js jetstream.JetStream, replicas int) (*KVJournal, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI journal requires JetStream and one to five replicas")
	}
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       journalBucket,
		Description:  "Durable OCI mutation intent and resource ownership",
		MaxValueSize: journalMaxValueSize,
		History:      5,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
		Compression:  true,
	})
	if err != nil {
		if !errors.Is(err, jetstream.ErrBucketExists) {
			return nil, fmt.Errorf("create OCI journal bucket: %w", err)
		}
		kv, err = js.KeyValue(ctx, journalBucket)
		if err != nil {
			return nil, fmt.Errorf("open existing OCI journal bucket: %w", err)
		}
		status, statusErr := kv.Status(ctx)
		if statusErr != nil {
			return nil, fmt.Errorf("inspect OCI journal bucket: %w", statusErr)
		}
		config := status.Config()
		if config.Replicas != replicas || config.Storage != jetstream.FileStorage || config.TTL != 0 || config.History < 2 || config.MaxValueSize > journalMaxValueSize {
			return nil, errors.New("existing OCI journal bucket has incompatible durability limits")
		}
	}
	return NewKVJournal(kv)
}

// NewKVJournal wraps a caller-provisioned regional JetStream KV bucket. The
// caller is responsible for using a durable, quorum-replicated bucket.
func NewKVJournal(kv jetstream.KeyValue) (*KVJournal, error) {
	if kv == nil {
		return nil, errors.New("OCI journal KV bucket is required")
	}
	return &KVJournal{kv: kv}, nil
}

func (journal *KVJournal) RecordIntent(ctx context.Context, intent OperationIntent) error {
	if err := validateIntent(intent); err != nil {
		return err
	}
	entry := journalEntry{SchemaVersion: journalSchema, Kind: "operation", Intent: intent}
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("encode OCI operation intent: %w", err)
	}
	key := operationKey(intent)
	_, err = journal.kv.Create(ctx, key, data)
	if err == nil {
		return nil
	}
	if !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("persist OCI operation intent: %w", err)
	}
	current, err := journal.read(ctx, key)
	if err != nil {
		return err
	}
	if current.Kind != "operation" || !sameIntent(current.Intent, intent) {
		return errors.New("OCI operation key was reused for a different mutation")
	}
	return nil
}

func (journal *KVJournal) GetResult(ctx context.Context, intent OperationIntent) (OperationResult, bool, error) {
	if err := validateIntent(intent); err != nil {
		return OperationResult{}, false, err
	}
	entry, err := journal.read(ctx, operationKey(intent))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return OperationResult{}, false, nil
	}
	if err != nil {
		return OperationResult{}, false, err
	}
	if entry.Kind != "operation" || !sameIntent(entry.Intent, intent) {
		return OperationResult{}, false, errors.New("OCI result lookup has no matching durable intent")
	}
	result := entry.Result
	if result.RecordedAt.IsZero() {
		result.Intent = entry.Intent
		return result, false, nil
	}
	result.Intent = entry.Intent
	return result, true, nil
}

// GetOperation returns the first committed intent for an exact operation key,
// including when the provider has not yet produced a durable result. Only the
// immutable key scope is supplied by the retrying caller; mutation details are
// recovered from the journal rather than reconstructed.
func (journal *KVJournal) GetOperation(ctx context.Context, scope OperationScope) (OperationIntent, bool, error) {
	if scope.Action == "" || scope.Key == "" || scope.Generation == 0 || scope.Owner == "" {
		return OperationIntent{}, false, errors.New("OCI operation lookup scope is incomplete")
	}
	if _, err := scope.Region.OCIRegion(); err != nil {
		return OperationIntent{}, false, err
	}
	keyIntent := OperationIntent{
		Action: scope.Action, Key: scope.Key, Region: scope.Region,
		Generation: scope.Generation, Owner: scope.Owner,
	}
	entry, err := journal.read(ctx, operationKey(keyIntent))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return OperationIntent{}, false, nil
	}
	if err != nil {
		return OperationIntent{}, false, err
	}
	intent := entry.Intent
	if entry.Kind != "operation" || intent.Action != scope.Action || intent.Key != scope.Key ||
		intent.Region != scope.Region || intent.Generation != scope.Generation || intent.Owner != scope.Owner {
		return OperationIntent{}, false, errors.New("OCI operation lookup has no matching durable intent")
	}
	return intent, true, nil
}

func (journal *KVJournal) read(ctx context.Context, key string) (journalEntry, error) {
	entry, err := journal.kv.Get(ctx, key)
	if err != nil {
		return journalEntry{}, err
	}
	return decodeJournalEntry(entry.Value())
}

func decodeJournalEntry(data []byte) (journalEntry, error) {
	var record journalEntry
	if err := json.Unmarshal(data, &record, json.RejectUnknownMembers(true)); err != nil {
		return journalEntry{}, fmt.Errorf("decode OCI journal record: %w", err)
	}
	if record.SchemaVersion != journalSchema {
		return journalEntry{}, errors.New("OCI journal record has unsupported schema version")
	}
	return record, nil
}

func (journal *KVJournal) volumeTerminated(ctx context.Context, config RegionConfig, volumeID string) (bool, error) {
	entry, err := journal.read(ctx, ownershipKey("volume-termination", volumeID))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	proof := entry.VolumeTermination
	if entry.Kind != "volume-termination" || proof.VolumeID != volumeID || proof.Region != config.Region ||
		proof.Owner != config.Owner || proof.CompartmentID != config.CompartmentID ||
		proof.AvailabilityDomain != config.AvailabilityDomain || proof.ObservedAt.IsZero() ||
		proof.ObservedAt.Location() != time.UTC {
		return false, errors.New("OCI volume termination proof has a different or corrupt scope")
	}
	return true, nil
}

func (journal *KVJournal) RecordVolumeTermination(ctx context.Context, config RegionConfig, volumeID string) error {
	if volumeID == "" || config.Owner == "" || config.Region == "" || config.CompartmentID == "" || config.AvailabilityDomain == "" {
		return errors.New("OCI volume termination proof requires complete scope")
	}
	proof := volumeTermination{VolumeID: volumeID, Region: config.Region, Owner: config.Owner,
		CompartmentID: config.CompartmentID, AvailabilityDomain: config.AvailabilityDomain,
		ObservedAt: time.Now().UTC()}
	data, err := json.Marshal(journalEntry{SchemaVersion: journalSchema, Kind: "volume-termination", VolumeTermination: proof})
	if err != nil {
		return err
	}
	if _, err := journal.kv.Create(ctx, ownershipKey("volume-termination", volumeID), data); err == nil {
		return nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("persist OCI volume termination proof: %w", err)
	}
	terminated, err := journal.volumeTerminated(ctx, config, volumeID)
	if err != nil {
		return err
	}
	if !terminated {
		return errors.New("OCI volume termination proof disappeared before readback")
	}
	return nil
}
